/* Treino — conteúdo gamificado (unidades, lições e exercícios com mnemônicos). */
window.TREINO_UNIDADES = [{"unidade": "SUS & Assistência Farmacêutica", "icone": "🏛️", "licoes": [{"titulo": "Princípios e diretrizes do SUS", "mnemo": "U-I-E + D-R-P — Princípios: Universalidade, Integralidade, Equidade. Diretrizes: Descentralização (direção única), Regionalização/hierarquização, Participação da comunidade.", "itens": [{"t": "fill", "frase": "O princípio da ___ garante acesso ao SUS a todos, sem exigir contribuição prévia.", "opcoes": ["Universalidade", "Equidade", "Integralidade", "Descentralização"], "resp": 0, "dica": "U de 'Universo': cabe todo mundo (é o U do U-I-E).", "exp": "Universalidade = saúde é direito de todos e dever do Estado (CF/88, art. 196), sem vínculo contributivo."}, {"t": "fill", "frase": "Tratar desigualmente os desiguais, priorizando quem mais precisa, é a ideia de ___.", "opcoes": ["Equidade", "Universalidade", "Hierarquização", "Resolutividade"], "resp": 0, "dica": "É o E do U-I-E: Equidade encerra o trio doutrinário.", "exp": "Equidade é construção doutrinária derivada da 'igualdade da assistência sem preconceitos ou privilégios' da Lei 8.080/90."}, {"t": "quiz", "p": "Qual das opções é DIRETRIZ organizativa do SUS, e não princípio doutrinário?", "opcoes": ["Descentralização com direção única em cada esfera", "Universalidade", "Integralidade", "Equidade"], "resp": 0, "exp": "As diretrizes do art. 198 da CF/88 são o D-R-P: descentralização, atendimento integral regionalizado/hierarquizado e participação da comunidade."}, {"t": "vf", "afirm": "A Constituição prevê atendimento integral com prioridade para as atividades preventivas, sem prejuízo dos serviços assistenciais.", "resp": true, "exp": "É a redação literal do art. 198, II, da CF/88 — o 'I' do U-I-E aplicado à organização do serviço."}, {"t": "vf", "afirm": "A Lei 8.080/90 traz literalmente o termo 'equidade' na lista de seus princípios.", "resp": false, "exp": "O texto legal fala em 'igualdade da assistência à saúde, sem preconceitos ou privilégios de qualquer espécie'. Equidade é leitura doutrinária desse princípio."}, {"t": "mem", "titulo": "Princípio/diretriz ↔ ideia-chave (U-I-E + D-R-P)", "pares": [["Universalidade", "Saúde para todos, sem contribuir"], ["Equidade", "Mais a quem mais precisa"], ["Integralidade", "Do preventivo ao curativo"], ["Descentralização", "Direção única em cada esfera"], ["Regionalização", "Rede hierarquizada por região"], ["Participação", "Conselhos e conferências"]]}, {"t": "quiz", "p": "Direção única em cada esfera de governo significa que a gestão do SUS é exercida por:", "opcoes": ["Ministério da Saúde, Secretaria Estadual e Secretaria Municipal, cada uma na sua esfera", "Apenas pelo Ministério da Saúde", "Conselhos de Saúde, em caráter executivo", "Comissões Intergestores Bipartite"], "resp": 0, "exp": "Art. 9º da Lei 8.080/90: direção única exercida pelo MS na União, pela SES no estado e pela SMS no município."}, {"t": "fill", "frase": "A ___ organiza os serviços por níveis de complexidade crescente, tendo a atenção primária como porta preferencial.", "opcoes": ["hierarquização", "universalidade", "paridade", "resolutividade"], "resp": 0, "dica": "É o R-H do D-R-P: regionalização anda de mãos dadas com hierarquização.", "exp": "Regionalização + hierarquização estruturam a rede: primária, especializada e hospitalar, com referência e contrarreferência."}]}, {"titulo": "Leis 8.080 e 8.142 e o Decreto 7.508", "mnemo": "80 ORGANIZA, 42 PARTICIPA — a 8.080/90 organiza ações e serviços; a 8.142/90 dá voz e dinheiro (COnselho + COnferência + repasse fundo a fundo). E o Decreto 7.508/11 REGIONALIZA (Região, Portas, RENASES/RENAME, COAP).", "itens": [{"t": "quiz", "p": "A Lei 8.142/90 dispõe principalmente sobre:", "opcoes": ["Participação da comunidade e transferências intergovernamentais de recursos", "Condições para promoção e recuperação da saúde", "Vigilância sanitária e epidemiológica", "Criação da CONITEC"], "resp": 0, "exp": "Lembre do '42 PARTICIPA': Conselho, Conferência e repasse fundo a fundo. A organização do sistema é da 8.080."}, {"t": "vf", "afirm": "A Lei 8.142/90 surgiu para reinserir temas que haviam sido vetados no texto original da Lei 8.080/90.", "resp": true, "exp": "Os vetos atingiram justamente participação da comunidade e transferências de recursos — devolvidos meses depois pela 8.142."}, {"t": "fill", "frase": "A Conferência de Saúde reúne-se a cada ___ anos para avaliar a situação de saúde e propor diretrizes.", "opcoes": ["4", "2", "5", "8"], "resp": 0, "dica": "Conferência = ConFerência de 4 em 4 (como eleição presidencial).", "exp": "Lei 8.142/90, art. 1º, §1º: Conferência a cada 4 anos, convocada pelo Executivo ou, extraordinariamente, pelo Conselho."}, {"t": "fill", "frase": "O Conselho de Saúde é órgão permanente e ___, atuando na formulação de estratégias e no controle da execução da política.", "opcoes": ["deliberativo", "meramente consultivo", "executivo", "judicante"], "resp": 0, "dica": "ConSelho = permanente e deliberativo; ConFerência = a cada 4 anos.", "exp": "Suas decisões são homologadas pelo chefe do poder legalmente constituído em cada esfera."}, {"t": "vf", "afirm": "Nos conselhos e conferências, a representação dos usuários é paritária em relação ao conjunto dos demais segmentos.", "resp": true, "exp": "Lei 8.142/90, art. 1º, §4º: usuários ocupam 50% das vagas, o mesmo que trabalhadores, gestores e prestadores somados."}, {"t": "quiz", "p": "No Decreto 7.508/11, o instrumento que formaliza as responsabilidades dos entes numa Região de Saúde é o:", "opcoes": ["COAP — Contrato Organizativo da Ação Pública", "Mapa da Saúde", "Plano Diretor de Investimento", "Termo de Ajuste Sanitário"], "resp": 0, "exp": "O COAP define responsabilidades, metas, indicadores e recursos entre União, estado e municípios da região."}, {"t": "quiz", "p": "São Portas de Entrada às ações e serviços de saúde nas Redes de Atenção, segundo o Decreto 7.508/11:", "opcoes": ["Atenção primária, urgência/emergência, atenção psicossocial e serviços especiais de acesso aberto", "Apenas a atenção primária", "Hospitais de referência e UPAs", "Farmácias e laboratórios credenciados"], "resp": 0, "exp": "São 4 portas. A atenção primária é a preferencial, mas não a única."}, {"t": "mem", "titulo": "Norma ↔ conteúdo principal", "pares": [["Lei 8.080/90", "Organiza ações e serviços"], ["Lei 8.142/90", "Participação + repasse de verba"], ["Decreto 7.508/11", "Região, portas, RENASES, COAP"], ["Lei 12.401/11", "CONITEC e AF no SUS"], ["CF/88 art. 196-200", "Saúde como direito de todos"]]}]}, {"titulo": "Ciclo da Assistência Farmacêutica", "mnemo": "SePAADD — Seleção, Programação, Aquisição, Armazenamento, Distribuição, Dispensação. 'SE Programa, Adquire, Armazena, Distribui e Dispensa.' A Seleção é o eixo: erra ali, erra o ciclo todo.", "itens": [{"t": "fill", "frase": "A ___ é a etapa central do ciclo: define quais medicamentos serão usados e condiciona todas as demais.", "opcoes": ["Seleção", "Programação", "Aquisição", "Dispensação"], "resp": 0, "dica": "É o 'Se' do SePAADD — primeira letra, primeira etapa.", "exp": "A seleção define a lista padronizada (base da REMUME/RENAME) e é atribuição da Comissão de Farmácia e Terapêutica."}, {"t": "quiz", "p": "Estimar as quantidades a serem adquiridas para um período, evitando falta e sobra, é a etapa de:", "opcoes": ["Programação", "Seleção", "Armazenamento", "Distribuição"], "resp": 0, "exp": "Métodos clássicos: perfil epidemiológico, consumo histórico, consumo ajustado e oferta de serviços."}, {"t": "mem", "titulo": "Etapa do SePAADD ↔ o que faz", "pares": [["Seleção", "Escolhe o que entra na lista"], ["Programação", "Estima quanto comprar"], ["Aquisição", "Compra pela via legal"], ["Armazenamento", "Guarda e conserva o estoque"], ["Distribuição", "Leva às unidades de saúde"], ["Dispensação", "Entrega ao paciente com orientação"]]}, {"t": "vf", "afirm": "A dispensação é ato privativo do farmacêutico e inclui a orientação sobre o uso correto do medicamento.", "resp": true, "exp": "É o último D do SePAADD e o momento de maior contato com o usuário — não é mera entrega de caixa."}, {"t": "fill", "frase": "No armazenamento, o critério ___ manda sair primeiro o lote com validade mais próxima.", "opcoes": ["PVPS / FEFO", "PEPS / FIFO", "Curva ABC", "Classificação XYZ"], "resp": 0, "dica": "PVPS: Primeiro que Vence, Primeiro que Sai — vence antes, sai antes.", "exp": "PVPS (FEFO) prioriza a validade; PEPS (FIFO) prioriza a data de entrada. Em medicamentos, o padrão é PVPS."}, {"t": "vf", "afirm": "As etapas do ciclo são independentes: uma seleção mal feita não compromete a programação nem a dispensação.", "resp": false, "exp": "O ciclo é sistêmico e cíclico — cada etapa alimenta a seguinte. Seleção ruim gera compra errada, estoque parado e falta na ponta."}, {"t": "quiz", "p": "Em um serviço novo, sem histórico de consumo confiável, o melhor método de programação costuma ser:", "opcoes": ["Perfil epidemiológico", "Consumo histórico", "Consumo ajustado", "Reposição automática por estoque mínimo"], "resp": 0, "exp": "Sem série histórica, parte-se da morbidade esperada da população e dos esquemas terapêuticos padronizados."}, {"t": "fill", "frase": "A análise ___ classifica os itens do estoque por valor investido (A, B e C), orientando o controle gerencial.", "opcoes": ["de Curva ABC", "de Curva XYZ", "de Pareto sanitário", "de ponto de pedido"], "resp": 0, "dica": "ABC = dinheiro; XYZ = criticidade (o quanto faz falta).", "exp": "Classe A: poucos itens que consomem a maior parte do recurso — exigem controle mais rígido."}]}, {"titulo": "RENAME, CONITEC e PCDT", "mnemo": "180 + 90 = 270 e RENAME de 2 em 2 — a CONITEC tem 180 dias para decidir, prorrogáveis por mais 90 (270 no total); a RENAME é atualizada a cada 2 anos (BI-anual: Rename = Relação BI-enal).", "itens": [{"t": "fill", "frase": "A CONITEC assessora o Ministério da Saúde na ___ de tecnologias no SUS e na elaboração de protocolos clínicos.", "opcoes": ["incorporação, exclusão ou alteração", "fiscalização sanitária", "precificação", "distribuição"], "resp": 0, "dica": "CONITEC = COmissão Nacional de Incorporação de TECnologias.", "exp": "Criada pela Lei 12.401/2011, que alterou a Lei 8.080/90 e disciplinou a assistência terapêutica no SUS."}, {"t": "quiz", "p": "Qual o prazo para o Ministério da Saúde decidir sobre um pedido de incorporação de tecnologia?", "opcoes": ["180 dias, prorrogáveis por até 90", "90 dias, prorrogáveis por até 180", "270 dias, improrrogáveis", "360 dias, prorrogáveis por 90"], "resp": 0, "exp": "180 + 90 = 270 dias no máximo. É o número mais cobrado do tema."}, {"t": "vf", "afirm": "A decisão final sobre incorporar uma tecnologia ao SUS é da própria CONITEC.", "resp": false, "exp": "A CONITEC RECOMENDA; a decisão final é do Ministério da Saúde (Secretaria responsável por ciência, tecnologia e inovação em saúde)."}, {"t": "fill", "frase": "A RENAME é atualizada a cada ___ anos, conforme o Decreto 7.508/11.", "opcoes": ["2", "1", "4", "5"], "resp": 0, "dica": "REname = Relação BI-enal: de 2 em 2.", "exp": "A RENAME orienta a padronização em todas as esferas; estados e municípios podem ampliá-la com recursos próprios."}, {"t": "vf", "afirm": "O processo de avaliação da CONITEC inclui consulta pública antes da recomendação final.", "resp": true, "exp": "Consulta pública é etapa obrigatória do rito (Decreto 7.646/2011), junto da avaliação de eficácia, segurança e custo-efetividade."}, {"t": "quiz", "p": "Sobre PCDT (Protocolos Clínicos e Diretrizes Terapêuticas), é correto afirmar:", "opcoes": ["Estabelecem critérios de diagnóstico, tratamento, doses e monitoramento no SUS", "Substituem a RENAME", "São elaborados exclusivamente pela Anvisa", "Têm caráter apenas informativo, sem efeito na dispensação"], "resp": 0, "exp": "No CEAF, o PCDT é o documento que define quem tem direito ao medicamento e quais exames são exigidos."}, {"t": "vf", "afirm": "O SUS pode custear medicamento de caráter experimental ou sem registro na Anvisa, desde que prescrito por especialista.", "resp": false, "exp": "A Lei 8.080/90 (art. 19-T) veda o pagamento, ressarcimento ou reembolso de medicamento experimental ou não autorizado pela Anvisa."}, {"t": "mem", "titulo": "Sigla ↔ significado", "pares": [["RENAME", "Lista nacional de medicamentos"], ["RENASES", "Lista nacional de ações e serviços"], ["CONITEC", "Recomenda incorporar tecnologia"], ["PCDT", "Protocolo clínico e terapêutico"], ["ATS", "Avaliação de tecnologias em saúde"], ["CFT", "Comissão de Farmácia e Terapêutica"]]}]}, {"titulo": "Componentes da AF e controle social", "mnemo": "BEE + 50-25-25 — Componentes: Básico (tripartite, atenção primária), Estratégico (o MS compra: programas/endemias), Especializado/CEAF (Grupos 1-2-3). Conselho de Saúde: 50% usuários, 25% trabalhadores, 25% gestores e prestadores.", "itens": [{"t": "fill", "frase": "O Componente ___ da Assistência Farmacêutica cobre os medicamentos da atenção primária e é financiado pelos três entes.", "opcoes": ["Básico", "Estratégico", "Especializado", "Suplementar"], "resp": 0, "dica": "É o primeiro B do BEE: Básico = básico da atenção primária = todo mundo paga.", "exp": "Financiamento tripartite (União, estado e município), com repasse fundo a fundo para custeio."}, {"t": "quiz", "p": "Medicamentos para tuberculose, hanseníase, HIV/aids e imunobiológicos pertencem a qual componente?", "opcoes": ["Estratégico", "Básico", "Especializado (CEAF)", "Hospitalar"], "resp": 0, "exp": "Componente Estratégico: doenças de perfil endêmico/programas nacionais, com aquisição e financiamento pelo Ministério da Saúde."}, {"t": "vf", "afirm": "Os medicamentos do Componente Básico são financiados exclusivamente pela União.", "resp": false, "exp": "Básico é TRIPARTITE. O que é exclusivo da União (MS) é o Componente Estratégico."}, {"t": "mem", "titulo": "Componente ↔ exemplo típico", "pares": [["Básico", "Losartana, metformina, AAS"], ["Estratégico", "Antirretrovirais e antituberculose"], ["Especializado (CEAF)", "Adalimumabe, insulina análoga"], ["Grupo 1A", "MS compra e distribui"], ["Grupo 2", "Estado adquire e dispensa"], ["Grupo 3", "Município, via bloco básico"]]}, {"t": "quiz", "p": "No CEAF, o Grupo 1A caracteriza-se por:", "opcoes": ["Aquisição centralizada pelo Ministério da Saúde", "Aquisição pelo estado com recurso próprio", "Financiamento tripartite pelo bloco básico", "Compra direta pelo município"], "resp": 0, "exp": "Grupo 1A: MS compra e distribui. Grupo 1B: MS repassa recursos e o estado compra. Grupo 2: estado. Grupo 3: município."}, {"t": "fill", "frase": "Na composição do Conselho de Saúde, os usuários ocupam ___ das vagas.", "opcoes": ["50%", "25%", "33%", "75%"], "resp": 0, "dica": "50-25-25: metade é do povo; o resto se divide entre trabalhadores e gestores/prestadores.", "exp": "Paridade dos usuários em relação ao conjunto dos demais segmentos (Lei 8.142/90 e Resolução CNS 453/2012)."}, {"t": "vf", "afirm": "O Conselho de Saúde aprecia e delibera sobre o Plano de Saúde e fiscaliza a movimentação dos recursos do fundo.", "resp": true, "exp": "É controle social com força deliberativa — não é apenas opinativo."}, {"t": "quiz", "p": "Para receber os repasses regulares do Fundo Nacional de Saúde, a Lei 8.142/90 exige do município, entre outros:", "opcoes": ["Fundo de Saúde, Conselho de Saúde e Plano de Saúde", "Apenas cadastro no CNES", "Contrato com operadora de plano privado", "Aprovação prévia da CONITEC"], "resp": 0, "exp": "A lista inclui ainda relatório de gestão, contrapartida orçamentária e plano de carreira, cargos e salários."}]}]}, {"unidade": "Farmacologia & Interações", "icone": "💊", "licoes": [{"titulo": "ADME: o caminho do fármaco", "mnemo": "L-ADME — Liberação (o comprimido se desfaz), Absorção (entra na circulação), Distribuição (chega aos tecidos), Metabolismo (o fígado transforma), Excreção (o rim/bile eliminam). Se algum passo muda, a concentração no alvo muda.", "itens": [{"t": "fill", "frase": "A fração da dose que chega INALTERADA à circulação sistêmica chama-se ___.", "opcoes": ["biodisponibilidade (F)", "clearance (CL)", "volume de distribuição (Vd)", "meia-vida (t½)"], "resp": 0, "dica": "É o 'A' do ADME medido em número: por via IV, F = 100% porque nada se perde no caminho.", "exp": "Biodisponibilidade é a fração da dose administrada que atinge a circulação sistêmica sem ter sido alterada. A via IV é a referência, com F = 1 (100%)."}, {"t": "quiz", "p": "Um fármaco oral tem baixa biodisponibilidade por sofrer intenso efeito de primeira passagem. Onde isso ocorre?", "opcoes": ["Metabolismo hepático (e de parede intestinal) antes da circulação sistêmica", "Filtração glomerular acelerada no rim", "Ligação irreversível à albumina plasmática", "Destruição pela flora do cólon após a absorção"], "resp": 0, "exp": "O sangue do trato gastrintestinal vai pela veia porta ao fígado antes de cair na circulação sistêmica; ali (e já na parede intestinal, via CYP3A4) parte do fármaco é metabolizada. Por isso propranolol, morfina e nitroglicerina têm F oral baixa."}, {"t": "vf", "afirm": "Fármacos com volume de distribuição (Vd) muito alto são facilmente removidos por hemodiálise.", "resp": false, "exp": "Falso. Vd alto significa que o fármaco está sequestrado nos tecidos, e não no plasma — justamente o compartimento que a diálise depura. Dialisam bem os de Vd baixo, baixa ligação proteica e baixo peso molecular (ex.: lítio, metanol, salicilato)."}, {"t": "mem", "titulo": "Ligue cada etapa do ADME ao seu marcador", "pares": [["Absorção", "Biodisponibilidade (F)"], ["Distribuição", "Volume de distribuição (Vd)"], ["Metabolismo + Excreção", "Clearance (CL)"], ["Tempo para cair 50%", "Meia-vida (t½)"], ["Perda antes da circulação", "Efeito de primeira passagem"]]}, {"t": "fill", "frase": "Reações de oxidação pelo CYP450 são de fase ___; glicuronidação e sulfatação são de fase ___.", "opcoes": ["I e II", "II e I", "I e I", "II e II"], "resp": 0, "exp": "Fase I (oxidação, redução, hidrólise — sobretudo CYP450) expõe ou insere um grupo funcional. Fase II (conjugação: glicuronidação, sulfatação, acetilação, glutationa) acopla uma molécula polar e facilita a excreção."}, {"t": "quiz", "p": "Em cinética de 1ª ordem, quantas meias-vidas são necessárias para atingir o estado de equilíbrio (steady state)?", "opcoes": ["Cerca de 4 a 5", "Exatamente 1", "Cerca de 10 a 12", "Não depende da meia-vida"], "resp": 0, "exp": "Após 4-5 meias-vidas atinge-se ~94-97% do platô — a mesma regra vale para a eliminação após suspender o fármaco. Só a dose de ataque encurta esse tempo; aumentar a dose de manutenção não."}, {"t": "vf", "afirm": "Fenitoína, etanol e AAS em doses altas seguem cinética de ordem zero (saturável).", "resp": true, "exp": "Verdadeiro. Nesses casos as enzimas saturam e passa-se a eliminar uma QUANTIDADE fixa por tempo, não uma fração. Pequenos aumentos de dose geram saltos desproporcionais na concentração e risco de toxicidade."}, {"t": "fill", "frase": "Na intoxicação por salicilatos, alcalinizar a urina com bicarbonato ___ a excreção do fármaco.", "opcoes": ["aumenta", "reduz", "não altera", "só altera se houver anúria"], "resp": 0, "dica": "Aprisionamento iônico: ácido fraco em meio alcalino fica ionizado — e o que está ionizado não volta pelo túbulo.", "exp": "O AAS é ácido fraco; em urina alcalina ele se ioniza, não é reabsorvido no túbulo e é eliminado. O raciocínio inverso vale para bases fracas, que saem melhor em urina ácida."}]}, {"titulo": "CYP450: os INDUTORES", "mnemo": "CRAP-GPS (indutores) — Carbamazepina, Rifampicina, Álcool crônico, Fenitoína (Phenytoin) / Fenobarbital, Griseofulvina, Primidona, Sulfonilureias e erva-de-São-João. Indutor = mais enzima = menos fármaco = FALHA terapêutica.", "itens": [{"t": "fill", "frase": "A rifampicina ___ o CYP3A4, ___ a concentração dos anticoncepcionais orais e pode causar falha contraceptiva.", "opcoes": ["induz / reduz", "inibe / eleva", "induz / eleva", "inibe / reduz"], "resp": 0, "dica": "O R do CRAP-GPS é o indutor mais potente da prova: rifampicina 'varre' o outro fármaco.", "exp": "A rifampicina é indutora potente de CYP3A4 (e da P-glicoproteína), acelerando o metabolismo de estrogênio/progestogênio. Recomenda-se método contraceptivo adicional durante e por semanas após o tratamento."}, {"t": "quiz", "p": "Paciente estável com varfarina inicia carbamazepina. O que se espera do INR?", "opcoes": ["Queda do INR, com risco de trombose", "Aumento do INR, com risco de sangramento", "Nenhuma alteração, pois não há interação", "Aumento do INR apenas se houver hepatopatia"], "resp": 0, "exp": "Carbamazepina (o C do CRAP-GPS) induz CYP2C9/3A4 e acelera o metabolismo da varfarina, derrubando o INR e a proteção antitrombótica. Costuma exigir monitorização estreita e aumento de dose."}, {"t": "vf", "afirm": "O efeito de um indutor enzimático é imediato, aparecendo poucas horas após a primeira dose.", "resp": false, "exp": "Falso. A indução depende de síntese de nova proteína enzimática e leva dias a 2-3 semanas para se instalar — e período semelhante para desaparecer após a suspensão. Já a INIBIÇÃO é rápida, em horas."}, {"t": "mem", "titulo": "CRAP-GPS: cada letra e seu indutor", "pares": [["C", "Carbamazepina"], ["R", "Rifampicina"], ["A", "Álcool (uso crônico)"], ["P", "Fenitoína / Fenobarbital"], ["G", "Griseofulvina"], ["S", "Erva-de-São-João"]]}, {"t": "fill", "frase": "Paciente transplantado em uso de ciclosporina começa a tomar erva-de-São-João por conta própria: há risco de ___ do enxerto.", "opcoes": ["rejeição", "nefrotoxicidade por excesso", "hipertricose grave", "hipercalemia"], "resp": 0, "dica": "O S do CRAP-GPS é fitoterápico: induz CYP3A4 E a P-glicoproteína — dobra o efeito de 'varrer'.", "exp": "O Hypericum perforatum induz CYP3A4 e P-gp, derrubando os níveis de ciclosporina, tacrolimo, antirretrovirais e contraceptivos. É uma das interações fitoterápicas mais cobradas."}, {"t": "quiz", "p": "Por que o etilista crônico (sem hepatopatia avançada) tem maior risco de hepatotoxicidade pelo paracetamol?", "opcoes": ["Indução do CYP2E1, que gera mais NAPQI e esgota a glutationa", "Inibição do CYP2E1, que acumula paracetamol inalterado", "Redução da absorção intestinal do paracetamol", "Aumento do volume de distribuição do paracetamol"], "resp": 0, "exp": "O álcool crônico (o A do CRAP-GPS) induz o CYP2E1, desviando mais paracetamol para o metabólito tóxico NAPQI, enquanto os estoques de glutationa estão baixos. O antídoto, N-acetilcisteína, repõe o precursor da glutationa."}, {"t": "vf", "afirm": "Ao suspender um indutor enzimático, o fármaco-substrato pode atingir níveis tóxicos se a dose tiver sido aumentada durante a indução.", "resp": true, "exp": "Verdadeiro. Ao retirar o indutor, as enzimas voltam ao nível basal em 1-3 semanas e a dose 'corrigida para cima' passa a ser excessiva. Toda entrada e toda saída de indutor exige replanejamento da dose."}]}, {"titulo": "CYP450: os INIBIDORES", "mnemo": "SICKFACES.COM (inibidores) — Sodium valproate (valproato), Isoniazida, Cimetidina, Ketoconazol/azólicos, Fluconazol, Álcool agudo/Amiodarona, Cloranfenicol, Eritromicina e claritromicina, Sulfonamidas, Ciprofloxacino, Omeprazol, Metronidazol. Inibidor = menos enzima ativa = mais fármaco = TOXICIDADE.", "itens": [{"t": "fill", "frase": "Inibição enzimática eleva o nível do substrato em ___, enquanto a indução leva ___.", "opcoes": ["horas / dias a semanas", "dias / horas", "semanas / meses", "minutos / horas"], "resp": 0, "dica": "Inibir é apagar o interruptor (rápido); induzir é construir a fábrica de enzimas (lento).", "exp": "A inibição é competitiva/direta sobre a enzima já existente, com efeito em horas a poucos dias. A indução exige transcrição e síntese proteica, levando de 1 a 3 semanas."}, {"t": "quiz", "p": "Paciente em varfarina com INR estável recebe fluconazol para candidíase. Conduta esperada:", "opcoes": ["Antecipar o controle do INR pelo risco de sangramento", "Aumentar a dose da varfarina preventivamente", "Nada a fazer: azólicos não interagem com varfarina", "Suspender a varfarina definitivamente"], "resp": 0, "exp": "Fluconazol inibe CYP2C9, principal via da S-varfarina (o enantiômero mais potente), elevando o INR e o risco hemorrágico. Monitorização precoce e ajuste de dose são a conduta padrão."}, {"t": "vf", "afirm": "Claritromicina associada à sinvastatina aumenta o risco de miopatia e rabdomiólise.", "resp": true, "exp": "Verdadeiro. Claritromicina é inibidora potente de CYP3A4 (o 'C' de SICKFACES.COM), e a sinvastatina depende dessa via — a exposição sobe várias vezes. A associação é contraindicada; azitromicina é alternativa mais segura."}, {"t": "mem", "titulo": "SICKFACES.COM: letra e inibidor", "pares": [["S", "Valproato de sódio"], ["I", "Isoniazida"], ["K / F", "Cetoconazol e fluconazol"], ["A", "Amiodarona / álcool agudo"], ["E", "Eritromicina e claritromicina"], ["O / M", "Omeprazol e metronidazol"]]}, {"t": "fill", "frase": "O suco de ___ inibe o CYP3A4 da parede intestinal e aumenta a biodisponibilidade da sinvastatina e do felodipino.", "opcoes": ["toranja (grapefruit)", "laranja-lima", "limão-taiti", "maracujá"], "resp": 0, "dica": "Não está na sigla, mas cai igual: a toranja é o 'inibidor de mesa'.", "exp": "As furanocumarinas da toranja inativam o CYP3A4 intestinal de forma irreversível, e o efeito dura cerca de 24-72 h. Resultado: picos de sinvastatina, felodipino, ciclosporina e outros substratos 3A4."}, {"t": "quiz", "p": "Paciente em uso de metronidazol ingere bebida alcoólica e apresenta rubor, náusea, vômito e taquicardia. O mecanismo é:", "opcoes": ["Efeito dissulfiram-like, com acúmulo de acetaldeído", "Indução do CYP2E1 pelo metronidazol", "Quelação do álcool no estômago", "Bloqueio da absorção intestinal do etanol"], "resp": 0, "exp": "O metronidazol inibe a aldeído-desidrogenase, e o acetaldeído se acumula. Orienta-se evitar álcool durante o tratamento e por cerca de 24-48 h após a última dose (o mesmo vale para cefalosporinas com cadeia NMTT)."}, {"t": "vf", "afirm": "O omeprazol é inibidor do CYP2C19 e, por isso, pode reduzir o efeito antiplaquetário do clopidogrel.", "resp": true, "exp": "Verdadeiro — é a pegadinha clássica: o inibidor aqui REDUZ o efeito, porque o clopidogrel é pró-fármaco e precisa do CYP2C19 para ser ativado. Prefere-se pantoprazol, de menor inibição dessa isoenzima."}, {"t": "fill", "frase": "A amiodarona inibe a P-gp e o CYP e pode ___ a concentração sérica da digoxina.", "opcoes": ["dobrar", "reduzir à metade", "não alterar", "zerar"], "resp": 0, "dica": "O A de SICKFACES.COM tem meia-vida de semanas: a interação persiste muito depois de suspender.", "exp": "Amiodarona reduz o efluxo pela P-glicoproteína e a depuração da digoxina, podendo dobrar a digoxinemia. Costuma-se reduzir a dose de digoxina em ~50% e monitorar sinais de intoxicação."}]}, {"titulo": "Pró-fármacos, transportadores e clearance", "mnemo": "CLEVA-C (pró-fármacos: precisam ser ativados) — Clopidogrel, Levodopa, Enalapril, Valaciclovir, Azatioprina, Codeína. Bônus: T de Tamoxifeno. Para transportador, lembre 'P-gp = Porta que Ganha Pra fora' (bomba de efluxo).", "itens": [{"t": "mem", "titulo": "Pró-fármaco → forma ativa", "pares": [["Enalapril", "Enalaprilato"], ["Valaciclovir", "Aciclovir"], ["Codeína (via CYP2D6)", "Morfina"], ["Azatioprina", "6-mercaptopurina"], ["Levodopa", "Dopamina"], ["Tamoxifeno (via CYP2D6)", "Endoxifeno"]]}, {"t": "quiz", "p": "Mulher com câncer de mama em tamoxifeno inicia fluoxetina para fogachos. Qual o problema?", "opcoes": ["Fluoxetina inibe CYP2D6 e reduz a formação de endoxifeno, o metabólito ativo", "Fluoxetina induz CYP2D6 e causa toxicidade do tamoxifeno", "Fluoxetina desloca o tamoxifeno da albumina e causa overdose", "Não há interação relevante entre os dois"], "resp": 0, "exp": "O tamoxifeno é pró-fármaco dependente do CYP2D6. Inibidores potentes (fluoxetina, paroxetina, bupropiona) reduzem o endoxifeno e podem comprometer a eficácia antitumoral — preferem-se venlafaxina, desvenlafaxina ou citalopram."}, {"t": "vf", "afirm": "A codeína só produz analgesia após conversão em morfina, e metabolizadores lentos do CYP2D6 têm resposta ruim.", "resp": true, "exp": "Verdadeiro. Cerca de 10% da codeína é convertida em morfina pelo CYP2D6. Metabolizadores lentos têm analgesia insuficiente; já os ultrarrápidos correm risco de depressão respiratória, motivo da contraindicação em crianças pequenas."}, {"t": "fill", "frase": "A P-glicoproteína é uma bomba de ___ que joga o fármaco de volta para a luz intestinal, ___ a absorção.", "opcoes": ["efluxo / reduzindo", "influxo / aumentando", "efluxo / aumentando", "influxo / reduzindo"], "resp": 0, "dica": "P-gp = Pra-fora. Rifampicina e erva-de-São-João a induzem; verapamil, amiodarona e claritromicina a inibem.", "exp": "A P-gp (ABCB1) faz efluxo ativo no enterócito, na barreira hematoencefálica e no túbulo renal, limitando absorção e penetração tecidual. Digoxina, dabigatrana e ciclosporina são substratos clássicos."}, {"t": "quiz", "p": "A depuração (clearance) de um fármaco cai pela metade e a dose de manutenção não muda. O que acontece no equilíbrio?", "opcoes": ["A concentração plasmática média dobra", "A concentração plasmática média cai pela metade", "A concentração não se altera, só o tempo até o equilíbrio", "O volume de distribuição dobra"], "resp": 0, "exp": "No estado de equilíbrio, Css = (F × dose/intervalo) ÷ CL. Com o clearance reduzido à metade e a mesma dose, a concentração dobra — a razão para ajustar doses na insuficiência renal ou hepática."}, {"t": "vf", "afirm": "A dose de ATAQUE depende do volume de distribuição, e a de MANUTENÇÃO depende do clearance.", "resp": true, "exp": "Verdadeiro. Dose de ataque ≈ (Vd × concentração-alvo) ÷ F, pois serve para 'encher' o compartimento. A manutenção ≈ (CL × concentração-alvo) ÷ F, pois apenas repõe o que é eliminado."}, {"t": "fill", "frase": "Um fármaco com meia-vida de 12 h leva cerca de ___ para atingir o estado de equilíbrio.", "opcoes": ["2 a 2,5 dias", "12 horas", "1 semana", "1 mês"], "resp": 0, "dica": "Regra das 4-5 meias-vidas: 4 × 12 h = 48 h.", "exp": "Quatro a cinco meias-vidas correspondem a 48-60 h, ou seja, cerca de 2 a 2,5 dias. É o mesmo tempo necessário para eliminar praticamente todo o fármaco após a suspensão."}, {"t": "quiz", "p": "O transportador OATP1B1 (gene SLCO1B1) é relevante em farmacogenética porque:", "opcoes": ["Capta estatinas para o hepatócito; variantes aumentam o risco de miopatia", "Elimina estatinas pelo rim; variantes causam nefrotoxicidade", "Ativa o clopidogrel no fígado", "Metaboliza a varfarina no intestino"], "resp": 0, "exp": "O OATP1B1 faz a captação hepática das estatinas; variantes de SLCO1B1 elevam a exposição sistêmica da sinvastatina e o risco de miopatia. A gemfibrozila inibe esse transportador e a glicuronidação, o que explica a rabdomiólise da associação estatina + fibrato."}]}, {"titulo": "Farmacodinâmica e interações à mesa", "mnemo": "PRATO DE RISCO — T.T.V.C.J.: Toranja (inibe CYP3A4), Tiramina (queijo/vinho + IMAO = crise hipertensiva), Vitamina K (folhas verdes reduzem a varfarina), Cátions (leite, antiácido e ferro quelam tetraciclina e quinolona), Jejum obrigatório (levotiroxina e alendronato).", "itens": [{"t": "fill", "frase": "Um antagonista ___ desloca a curva dose-resposta para a direita e mantém a Emax; o ___ reduz a Emax.", "opcoes": ["competitivo / não competitivo", "não competitivo / competitivo", "parcial / inverso", "inverso / competitivo"], "resp": 0, "dica": "Competitivo se vence com mais dose (só a potência piora); não competitivo derruba o teto do efeito.", "exp": "O antagonista competitivo disputa o mesmo sítio de forma reversível: aumenta a CE50 (menor potência) mas o efeito máximo é recuperável com dose maior. O não competitivo/irreversível reduz o número de receptores úteis e derruba a Emax."}, {"t": "quiz", "p": "Potência e eficácia de um fármaco correspondem, respectivamente, a:", "opcoes": ["CE50 e efeito máximo (Emax)", "Emax e CE50", "Meia-vida e clearance", "Índice terapêutico e biodisponibilidade"], "resp": 0, "exp": "Potência é a dose necessária para metade do efeito máximo (CE50) — quanto menor, mais potente. Eficácia é o efeito máximo alcançável (Emax) e é clinicamente mais relevante que a potência."}, {"t": "vf", "afirm": "A buprenorfina é agonista parcial do receptor mu e pode precipitar abstinência em quem usa agonista pleno.", "resp": true, "exp": "Verdadeiro. Por ter alta afinidade e atividade intrínseca parcial, ela desloca o agonista pleno do receptor e entrega menos efeito, desencadeando abstinência. Por isso se exige janela de abstinência antes de iniciá-la."}, {"t": "mem", "titulo": "Alimento/nutriente → fármaco afetado", "pares": [["Suco de toranja", "Sinvastatina, felodipino"], ["Tiramina (queijo, vinho)", "IMAO: crise hipertensiva"], ["Vitamina K (folhas verdes)", "Varfarina: queda do INR"], ["Leite, antiácido, ferro", "Tetraciclina e quinolona"], ["Jejum de 30-60 min", "Levotiroxina e alendronato"]]}, {"t": "fill", "frase": "Ciprofloxacino deve ser separado de antiácidos e do leite porque ocorre ___ e queda da absorção.", "opcoes": ["quelação com cátions divalentes", "indução do CYP3A4", "efeito de primeira passagem", "aprisionamento iônico gástrico"], "resp": 0, "dica": "O C do T.T.V.C.J.: Ca, Mg, Al, Fe e Zn formam complexos insolúveis com quinolonas e tetraciclinas.", "exp": "Cátions di e trivalentes formam quelatos não absorvíveis com quinolonas e tetraciclinas, podendo reduzir muito a biodisponibilidade. A orientação é espaçar: o antibiótico 2 h antes ou 4-6 h depois do cátion."}, {"t": "quiz", "p": "Qual associação NÃO deve ser feita pelo risco de hipotensão grave e refratária?", "opcoes": ["Sildenafila + nitrato (isossorbida ou nitroglicerina)", "Losartana + hidroclorotiazida", "Metformina + empagliflozina", "Omeprazol + domperidona"], "resp": 0, "exp": "Ambos elevam o GMPc: o nitrato doa óxido nítrico e a sildenafila inibe a fosfodiesterase-5 que o degrada — é sinergismo farmacodinâmico com vasodilatação maciça. Respeitar 24 h (sildenafila) a 48 h (tadalafila) antes de um nitrato."}, {"t": "vf", "afirm": "Alopurinol associado à azatioprina exige redução expressiva da dose do imunossupressor pelo risco de mielotoxicidade.", "resp": true, "exp": "Verdadeiro. O alopurinol inibe a xantina-oxidase, que degrada a 6-mercaptopurina derivada da azatioprina, elevando os metabólitos ativos. Reduz-se a azatioprina para cerca de 25-33% da dose, ou evita-se a associação."}, {"t": "fill", "frase": "Paciente em lítio inicia ibuprofeno e hidroclorotiazida: espera-se ___ da litemia.", "opcoes": ["aumento, com risco de intoxicação", "queda, com perda de eficácia", "nenhuma mudança", "queda apenas nas primeiras 24 h"], "resp": 0, "dica": "Lítio é fármaco de índice terapêutico estreito e 'anda junto' com o sódio no túbulo proximal.", "exp": "AINEs, tiazídicos e IECA reduzem a excreção renal de lítio e elevam a litemia. Como o índice terapêutico é estreito (alvo ~0,6-1,2 mEq/L), o monitoramento sérico é obrigatório ao iniciar esses fármacos."}]}]}, {"unidade": "Antimicrobianos & Resistência", "icone": "🦠", "licoes": [{"titulo": "Alvos e mecanismos de ação", "mnemo": "PRA RIR MUITO, DÊ FOCO — os 5 alvos: P=Parede (beta-lactâmicos, vancomicina), R=Ribossomo (aminoglicosídeos 30S, macrolídeos/clindamicina/linezolida 50S), M=Membrana (polimixinas, daptomicina), D=DNA (quinolonas, metronidazol, rifampicina no RNA), FO=FOlato (sulfametoxazol + trimetoprima).", "itens": [{"t": "fill", "frase": "Os beta-lactâmicos inibem a síntese da parede ao se ligarem às ___, bloqueando a transpeptidação do peptidoglicano.", "opcoes": ["PBP (proteínas ligadoras de penicilina)", "DNA-girases", "subunidades 50S", "porinas OprD"], "resp": 0, "dica": "\"Pra Rir\" — o P é de Parede, e a parede se monta nas PBP.", "exp": "PBP são transpeptidases. Bloqueadas, o peptidoglicano não faz ligações cruzadas e a bactéria lisa: efeito bactericida tempo-dependente."}, {"t": "quiz", "p": "Qual antimicrobiano age na subunidade 50S do ribossomo?", "opcoes": ["Clindamicina", "Gentamicina", "Ciprofloxacino", "Vancomicina"], "resp": 0, "exp": "50S: macrolídeos, clindamicina, linezolida e cloranfenicol. 30S: aminoglicosídeos e tetraciclinas. Ciprofloxacino age na DNA-girase e vancomicina na parede."}, {"t": "vf", "afirm": "A vancomicina inibe a parede ligando-se ao terminal D-Ala-D-Ala do precursor do peptidoglicano, e não às PBP.", "resp": true, "exp": "Ela sequestra o substrato, não a enzima. Por isso a troca do terminal para D-Ala-D-Lac (VanA) gera resistência."}, {"t": "mem", "titulo": "Classe ↔ alvo de ação", "pares": [["Beta-lactâmicos", "Parede: ligam-se às PBP"], ["Aminoglicosídeos", "Ribossomo 30S"], ["Macrolídeos", "Ribossomo 50S"], ["Fluoroquinolonas", "DNA-girase e topoisomerase IV"], ["Sulfametoxazol-trimetoprima", "Via do folato"], ["Polimixina B", "Membrana externa (lipídeo A)"]]}, {"t": "fill", "frase": "As fluoroquinolonas inibem a DNA-___ (topoisomerase II) e a topoisomerase IV.", "opcoes": ["girase", "polimerase", "ligase", "helicase"], "resp": 0, "dica": "\"Dê\" de DNA: a quinolona embaraça o DNA que a girase deveria desenrolar.", "exp": "A girase predomina em Gram-negativos e a topoisomerase IV em Gram-positivos. Mutações em gyrA/parC são a resistência clássica."}, {"t": "quiz", "p": "O metronidazol depende de qual etapa para se tornar ativo?", "opcoes": ["Redução do grupo nitro em meio anaeróbio, gerando radicais que quebram o DNA", "Ligação à PBP2a", "Inibição da di-hidropteroato sintase", "Bloqueio da RNA-polimerase"], "resp": 0, "exp": "Só bactérias anaeróbias (e protozoários) têm potencial redox baixo o bastante para ativá-lo — daí não haver ação sobre aeróbios."}, {"t": "vf", "afirm": "A linezolida age no ribossomo impedindo a formação do complexo de iniciação 70S, ligando-se à subunidade 50S.", "resp": true, "exp": "Mecanismo único, sem resistência cruzada com macrolídeos e clindamicina. É bacteriostática para Staphylococcus e Enterococcus."}, {"t": "fill", "frase": "O sulfametoxazol inibe a di-hidropteroato sintase e a trimetoprima inibe a ___ redutase — bloqueio sequencial da via do folato.", "opcoes": ["di-hidrofolato", "di-hidropteroato", "timidilato", "ribonucleotídeo"], "resp": 0, "dica": "\"FOco\" = FOlato: dois degraus seguidos da mesma escada.", "exp": "A inibição sequencial torna a associação sinérgica e bactericida, enquanto cada droga isolada é bacteriostática."}]}, {"titulo": "Espectro e escolha empírica", "mnemo": "CAMPO-Z (quem cobre Pseudomonas): C=Cefepima/Ceftazidima, A=Aminoglicosídeos (amicacina), M=Meropenem/Imipenem (nunca ertapenem), P=Piperacilina-tazobactam, O=quinOlonas (cipro/levo), Z=aZtreonam. Fora do campo: polimixina e ceftazidima-avibactam nas multirresistentes.", "itens": [{"t": "quiz", "p": "Qual carbapenêmico NÃO cobre Pseudomonas aeruginosa?", "opcoes": ["Ertapenem", "Meropenem", "Imipenem", "Doripenem"], "resp": 0, "exp": "O ertapenem cobre ESBL e anaeróbios, mas não Pseudomonas, Acinetobacter nem Enterococcus. Tem meia-vida longa (1x/dia)."}, {"t": "fill", "frase": "Na sepse de foco abdominal com risco de ESBL sem suspeita de Pseudomonas, o carbapenêmico de escolha, por poupar espectro, é o ___.", "opcoes": ["ertapenem", "meropenem", "imipenem", "doripenem"], "resp": 0, "dica": "No CAMPO-Z, o M é de Meropenem/Imipenem — o ertapenem ficou de fora do campo.", "exp": "Escolher o carbapenêmico sem ação antipseudomonas quando ela não é necessária reduz pressão seletiva sobre a Pseudomonas."}, {"t": "vf", "afirm": "A cefazolina (1ª geração) tem boa atividade contra Gram-negativos hospitalares, incluindo Pseudomonas.", "resp": false, "exp": "Cefalosporinas de 1ª geração são drogas de Gram-positivos (MSSA, estreptococos) e poucos Gram-negativos comunitários (E. coli, Proteus, Klebsiella)."}, {"t": "mem", "titulo": "Antimicrobiano ↔ nicho de espectro", "pares": [["Ceftriaxona", "Gram- comunitários; sem Pseudomonas"], ["Metronidazol", "Anaeróbios abaixo do diafragma"], ["Azitromicina", "Atípicos (Mycoplasma, Legionella)"], ["Vancomicina", "Só Gram+, inclusive MRSA"], ["Ampicilina", "Enterococcus faecalis e Listeria"], ["Amicacina", "Gram- aeróbios; sinergia"]]}, {"t": "quiz", "p": "Qual opção NÃO cobre anaeróbios de forma confiável?", "opcoes": ["Ceftriaxona", "Piperacilina-tazobactam", "Metronidazol", "Clindamicina"], "resp": 0, "exp": "As cefalosporinas (exceto cefoxitina) não cobrem anaeróbios: em foco abdominal a ceftriaxona precisa de metronidazol associado."}, {"t": "fill", "frase": "Na meningite bacteriana do paciente com mais de 50 anos, acrescenta-se ___ ao esquema para cobrir Listeria monocytogenes.", "opcoes": ["ampicilina", "ceftriaxona", "vancomicina", "clindamicina"], "resp": 0, "dica": "Listeria não está em nenhuma cefalosporina — só a AMPicilina alcança.", "exp": "Listeria é intrinsecamente resistente a todas as cefalosporinas. Alternativa em alergia: sulfametoxazol-trimetoprima."}, {"t": "vf", "afirm": "Em bacteremia por S. aureus sensível à meticilina (MSSA), oxacilina ou cefazolina são superiores à vancomicina.", "resp": true, "exp": "A vancomicina tem morte bacteriana mais lenta e maior falência no MSSA; descalonar para beta-lactâmico antiestafilocócico reduz mortalidade."}, {"t": "quiz", "p": "Paciente com pneumonia comunitária grave em UTI. Qual esquema empírico contempla pneumococo e atípicos?", "opcoes": ["Ceftriaxona + azitromicina", "Ceftriaxona isolada", "Cefazolina + metronidazol", "Amicacina + vancomicina"], "resp": 0, "exp": "Beta-lactâmico + macrolídeo (ou quinolona respiratória isolada) é o padrão: nenhum beta-lactâmico cobre germes atípicos, que não têm parede celular clássica."}]}, {"titulo": "Mecanismos de resistência", "mnemo": "ESKAPE — os que \"escapam\" do arsenal: E=Enterococcus faecium (VRE), S=Staphylococcus aureus (MRSA), K=Klebsiella pneumoniae (ESBL/KPC), A=Acinetobacter baumannii, P=Pseudomonas aeruginosa (porina/efluxo), E=Enterobacter (AmpC).", "itens": [{"t": "fill", "frase": "A resistência do MRSA vem do gene mecA, que codifica a ___, uma transpeptidase com baixa afinidade pelos beta-lactâmicos.", "opcoes": ["PBP2a", "AmpC", "VanA", "KPC"], "resp": 0, "dica": "No ESKAPE, o S de S. aureus troca a fechadura: alvo alterado, não enzima.", "exp": "Por alterar o alvo, o MRSA é resistente a TODOS os beta-lactâmicos clássicos (exceto ceftarolina), mesmo que o teste in vitro sugira sensibilidade."}, {"t": "quiz", "p": "Qual é o mecanismo predominante de resistência aos aminoglicosídeos?", "opcoes": ["Enzimas modificadoras (acetil/adenil/fosfotransferases)", "Alteração da PBP2a", "Troca de D-Ala-D-Ala por D-Ala-D-Lac", "Hiperprodução de folato"], "resp": 0, "exp": "As enzimas modificadoras impedem a ligação ao ribossomo 30S. A amicacina resiste melhor a elas do que a gentamicina."}, {"t": "vf", "afirm": "ESBL são beta-lactamases que hidrolisam cefalosporinas de amplo espectro e aztreonam, mas são inibidas por clavulanato e não hidrolisam carbapenêmicos.", "resp": true, "exp": "É a definição fenotípica de ESBL. Em infecção grave, o tratamento de escolha continua sendo carbapenêmico."}, {"t": "mem", "titulo": "Germe/enzima ↔ resistência", "pares": [["MRSA", "mecA → PBP2a (alvo alterado)"], ["ESBL", "Hidrolisa cefalosporinas de 3ª ger."], ["KPC", "Carbapenemase de classe A"], ["VRE (VanA)", "D-Ala-D-Ala vira D-Ala-D-Lac"], ["Pseudomonas", "Perda da porina OprD + efluxo"], ["Enterobacter", "AmpC induzível cromossômica"]]}, {"t": "quiz", "p": "Klebsiella produtora de KPC em bacteremia. Qual afirmação é correta?", "opcoes": ["Ceftazidima-avibactam é opção terapêutica, pois o avibactam inibe carbapenemases de classe A", "Carbapenêmico em monoterapia é o padrão-ouro", "Clavulanato restaura a atividade da ceftriaxona", "A resistência é sempre por perda de porina"], "resp": 0, "exp": "Avibactam inibe classes A (KPC) e C (AmpC), mas não metalo-beta-lactamases (NDM/VIM) — nestas, associa-se aztreonam."}, {"t": "vf", "afirm": "Enterobacter, Serratia e Citrobacter podem desenvolver resistência à ceftriaxona durante o tratamento por desrepressão da AmpC.", "resp": true, "exp": "É o grupo AmpC induzível: mesmo sensíveis no antibiograma inicial, podem falhar. Preferir cefepima ou carbapenêmico em infecção grave."}, {"t": "fill", "frase": "A resistência plasmidial às polimixinas é mediada pelo gene ___, que adiciona fosfoetanolamina ao lipídeo A.", "opcoes": ["mcr-1", "mecA", "vanB", "gyrA"], "resp": 0, "dica": "Polimixina = membrana; mudar a carga do lipídeo A é \"trocar a fechadura\" da membrana.", "exp": "A modificação reduz a carga negativa da membrana externa e impede a ligação eletrostática da polimixina. Por ser plasmidial, dissemina-se entre espécies."}, {"t": "quiz", "p": "A produção de beta-lactamase pelo H. influenzae é exemplo de qual mecanismo geral de resistência?", "opcoes": ["Inativação enzimática do fármaco", "Alteração do sítio-alvo", "Redução da permeabilidade", "Bomba de efluxo"], "resp": 0, "exp": "Os quatro mecanismos gerais são: inativação enzimática, alteração do alvo, redução da permeabilidade/efluxo e via metabólica alternativa (bypass)."}]}, {"titulo": "PK/PD: tempo × concentração", "mnemo": "BLOCo do TEMPO (T>CIM): B=Beta-lactâmicos, L=Lincosamidas (clindamicina), O=Oxazolidinonas (linezolida), C=Claritro e demais macrolídeos. FADMe da CONCENTRAÇÃO (Cpico/CIM): F=Fluoroquinolonas, A=Aminoglicosídeos, D=Daptomicina, Me=Metronidazol.", "itens": [{"t": "fill", "frase": "Beta-lactâmicos são ___-dependentes: o índice que prevê eficácia é a fração do intervalo com concentração livre acima da CIM (T>CIM).", "opcoes": ["tempo", "concentração", "peso", "pH"], "resp": 0, "dica": "BLOCo do TEMPO — o B abre a lista.", "exp": "Aumentar a dose pontual pouco acrescenta; o que melhora o desfecho é fracionar mais, infundir em tempo estendido ou usar infusão contínua."}, {"t": "quiz", "p": "Por que a infusão estendida (4 h) de piperacilina-tazobactam é usada na sepse grave?", "opcoes": ["Aumenta o tempo acima da CIM, otimizando o índice PK/PD", "Eleva o pico sérico, que é o índice de eficácia", "Reduz a nefrotoxicidade dose-dependente", "Permite dose única diária"], "resp": 0, "exp": "Em germes com CIM elevada e pacientes críticos, o prolongamento da infusão é a manobra que mais aumenta o T>CIM sem elevar a dose total."}, {"t": "vf", "afirm": "A dose única diária de aminoglicosídeo aproveita a morte concentração-dependente e o efeito pós-antibiótico, com menor nefrotoxicidade que a dose fracionada.", "resp": true, "exp": "A captação renal é saturável: intervalos maiores permitem que o córtex renal \"se limpe\", enquanto o pico alto maximiza a morte bacteriana."}, {"t": "mem", "titulo": "Fármaco ↔ índice PK/PD", "pares": [["Beta-lactâmicos", "T > CIM"], ["Aminoglicosídeos", "Cpico/CIM ≥ 8-10"], ["Fluoroquinolonas", "AUC24/CIM ≥ 125 (Gram-)"], ["Vancomicina", "AUC24/CIM 400-600"], ["Daptomicina", "Cpico/CIM e AUC/CIM"], ["Linezolida", "AUC/CIM e T>CIM"]]}, {"t": "vf", "afirm": "A vancomicina é concentração-dependente pura, por isso a estratégia ideal é dose única diária muito alta.", "resp": false, "exp": "Ela é AUC-dependente: a meta atual é AUC24/CIM de 400 a 600, monitorada de preferência por AUC (bayesiano) e não apenas pelo vale."}, {"t": "fill", "frase": "Para fluoroquinolonas contra Gram-negativos, a meta clássica de eficácia é AUC24/CIM ≥ ___.", "opcoes": ["125", "10", "400", "0,5"], "resp": 0, "dica": "FADMe: quinolona é do time da concentração — mas a meta se lê em AUC.", "exp": "Contra pneumococo, a meta usada é de cerca de 30-40. Metas subterapêuticas selecionam mutantes de gyrA rapidamente."}, {"t": "quiz", "p": "Na sepse, por que se recomenda dose de ataque de beta-lactâmicos, vancomicina e aminoglicosídeos independentemente da função renal?", "opcoes": ["São hidrofílicos e o volume de distribuição aumenta com a expansão volêmica", "A depuração hepática cai na sepse", "A ligação proteica aumenta muito", "A absorção oral fica errática"], "resp": 0, "exp": "A dose de ataque depende do volume de distribuição, não da depuração. A função renal ajusta a dose de manutenção, nunca a de ataque."}, {"t": "vf", "afirm": "O efeito pós-antibiótico prolongado dos aminoglicosídeos contra Gram-negativos justifica intervalos maiores entre as doses.", "resp": true, "exp": "A supressão do crescimento persiste horas após a concentração cair abaixo da CIM — o oposto dos beta-lactâmicos, cujo efeito pós-antibiótico é mínimo em Gram-negativos."}]}, {"titulo": "Stewardship e efeitos adversos", "mnemo": "OS 5 D: Diagnóstico certo (colher cultura antes), Droga certa (menor espectro eficaz), Dose certa (PK/PD, peso, função renal), Descalonamento em 48-72 h e Duração mínima eficaz.", "itens": [{"t": "fill", "frase": "Nos 5 D do stewardship, a reavaliação em 48-72 h com o resultado da cultura corresponde ao ___.", "opcoes": ["Descalonamento", "Diagnóstico", "Diluição", "Desinfecção"], "resp": 0, "dica": "5 D: Diagnóstico, Droga, Dose, Descalonamento, Duração.", "exp": "Descalonar é trocar o esquema empírico amplo pelo menor espectro eficaz — a intervenção de maior impacto sobre a pressão seletiva."}, {"t": "quiz", "p": "Urocultura de paciente assintomático, sem gestação e sem procedimento urológico previsto, com E. coli >100.000 UFC/mL. Conduta correta?", "opcoes": ["Não tratar: bacteriúria assintomática", "Tratar 7 dias com ceftriaxona", "Tratar 3 dias com fosfomicina", "Repetir a cultura e tratar se persistir"], "resp": 0, "exp": "Tratar bacteriúria assintomática só se aplica a gestantes e antes de procedimento urológico invasivo. Fora disso, gera resistência e C. difficile sem benefício."}, {"t": "vf", "afirm": "A terapia sequencial IV para VO é medida de stewardship quando há via oral funcionante e o fármaco tem boa biodisponibilidade, como levofloxacino, linezolida e metronidazol.", "resp": true, "exp": "Reduz custo, tempo de internação e infecção de corrente sanguínea associada a cateter, com eficácia equivalente."}, {"t": "mem", "titulo": "Fármaco ↔ efeito adverso marcante", "pares": [["Aminoglicosídeos", "Nefro e ototoxicidade"], ["Vancomicina", "Sd. do homem vermelho; nefro"], ["Linezolida", "Plaquetopenia; sd. serotoninérgica"], ["Clindamicina", "Colite por C. difficile"], ["Fluoroquinolonas", "Tendinite e prolongamento do QT"], ["Sulfametoxazol-TMP", "Hipercalemia e rash"]]}, {"t": "quiz", "p": "Paciente apresenta rubor cervicotorácico e prurido durante infusão rápida de vancomicina. Qual a conduta?", "opcoes": ["Reduzir a velocidade de infusão (mínimo 60 min) e usar anti-histamínico; não é alergia IgE", "Suspender definitivamente por anafilaxia", "Trocar por outro glicopeptídeo imediatamente", "Aumentar a dose para vencer a reação"], "resp": 0, "exp": "É liberação direta de histamina, dependente da velocidade de infusão — reação pseudoalérgica. Não contraindica o uso futuro da droga."}, {"t": "vf", "afirm": "A dosagem seriada de procalcitonina pode auxiliar a interromper antimicrobianos em infecções respiratórias baixas e sepse.", "resp": true, "exp": "Protocolos guiados por procalcitonina reduzem dias de antibiótico sem aumentar mortalidade. Ela apoia a decisão clínica, não a substitui."}, {"t": "fill", "frase": "O consumo hospitalar de antimicrobianos é monitorado pela ___ de uso, expressa em DDD por 100 leitos-dia.", "opcoes": ["densidade", "incidência", "prevalência", "letalidade"], "resp": 0, "dica": "É indicador do D de \"Dose\" no nível do hospital: quanto se consome por leito ocupado.", "exp": "DDD/100 leitos-dia permite comparar setores e períodos; alternativa mais fina é o DOT (days of therapy), que não sofre com ajuste de dose renal."}, {"t": "quiz", "p": "Sobre duração de tratamento, qual afirmação está correta?", "opcoes": ["Pneumonia comunitária pode ser tratada por 5 dias se houver estabilidade clínica em 48-72 h", "Todo tratamento deve durar no mínimo 14 dias", "Cistite não complicada exige 10 dias", "Duração longa previne resistência"], "resp": 0, "exp": "Cursos curtos são tão eficazes quanto os longos em várias infecções e reduzem resistência, C. difficile e toxicidade. Duração prolongada seleciona resistência, não a previne."}]}]}, {"unidade": "Exames Laboratoriais", "icone": "🧪", "licoes": [{"titulo": "Hemograma e anemias", "mnemo": "O VCM manda: MICRO (<80) = Ferro, Talassemia, Doença crônica | NORMO (80-100) = sangramento, hemólise, DRC | MACRO (>100) = B-F-A-H: B12, Folato, Álcool, Hipotireoidismo", "itens": [{"t": "fill", "frase": "A anemia é microcítica quando o VCM está abaixo de ___ fL.", "opcoes": ["80", "90", "100"], "resp": 0, "dica": "Régua do VCM: <80 micro, 80-100 normo, >100 macro.", "exp": "VCM de referência: 80-100 fL. Abaixo de 80 fL = microcitose (ferropriva, talassemia, doença crônica)."}, {"t": "quiz", "p": "Qual a causa mais comum de anemia microcítica e hipocrômica?", "opcoes": ["Anemia ferropriva", "Talassemia menor", "Anemia de doença crônica", "Anemia sideroblástica"], "resp": 0, "exp": "A deficiência de ferro é a carência nutricional mais prevalente e a principal causa de microcitose."}, {"t": "vf", "afirm": "Na anemia ferropriva a ferritina está baixa e a capacidade de ligação do ferro (TIBC/transferrina) está aumentada.", "resp": true, "exp": "Padrão clássico: ferro sérico baixo, ferritina baixa (<30 ng/mL), TIBC alta e saturação de transferrina <20%."}, {"t": "vf", "afirm": "Ferritina normal ou elevada exclui anemia de doença crônica.", "resp": false, "exp": "Ao contrário: a ferritina é proteína de fase aguda e costuma estar normal/alta na doença crônica. É a ferropriva que cursa com ferritina baixa."}, {"t": "mem", "titulo": "Hemograma: valores de referência", "pares": [["Hemoglobina (homem)", "13 - 17 g/dL"], ["Hemoglobina (mulher)", "12 - 16 g/dL"], ["VCM", "80 - 100 fL"], ["Leucócitos", "4.000 - 11.000 /mm³"], ["Plaquetas", "150.000 - 450.000 /mm³"], ["Reticulócitos", "0,5 - 2%"]]}, {"t": "fill", "frase": "A macrocitose megaloblástica é típica da deficiência de folato e de vitamina ___.", "opcoes": ["B12", "C", "D", "K"], "resp": 0, "dica": "Macro = B-F-A-H: B12, Folato, Álcool, Hipotireoidismo.", "exp": "B12 e folato prejudicam a síntese de DNA: hemácias grandes, neutrófilos hipersegmentados e LDH alto."}, {"t": "quiz", "p": "Reticulócitos ELEVADOS em um paciente anêmico indicam principalmente:", "opcoes": ["Medula respondendo (hemólise ou sangramento)", "Aplasia de medula", "Deficiência de ferro não tratada", "Talassemia menor"], "resp": 0, "exp": "Reticulócitos altos = anemia hiperproliferativa (perda ou destruição). Baixos = falha de produção (carencial, aplasia, DRC)."}, {"t": "vf", "afirm": "VCM baixo com RDW alto sugere ferropriva; VCM baixo com RDW normal sugere talassemia menor.", "resp": true, "exp": "O RDW mede anisocitose. A ferropriva é heterogênea (RDW alto); na talassemia as hemácias são pequenas e uniformes."}]}, {"titulo": "Função renal, TFG e eletrólitos", "mnemo": "Degraus da TFG: 90 - 60 - 45 - 30 - 15 (G1 ≥90 | G2 60-89 | G3a 45-59 | G3b 30-44 | G4 15-29 | G5 <15). E lembre: CKD-EPI 2021, SEM coeficiente de raça.", "itens": [{"t": "fill", "frase": "A fórmula recomendada para estimar a TFG hoje é a ___ 2021, sem coeficiente de raça.", "opcoes": ["CKD-EPI", "Cockcroft-Gault", "MDRD", "Schwartz"], "resp": 0, "dica": "Cockcroft-Gault ficou para ajuste de dose em bulas antigas; a estimativa padrão é CKD-EPI 2021.", "exp": "CKD-EPI 2021 (creatinina, idade e sexo) é a equação recomendada para estimar a TFG em adultos."}, {"t": "quiz", "p": "TFG estimada de 38 mL/min/1,73 m² corresponde a qual estágio de DRC?", "opcoes": ["G3b", "G3a", "G4", "G2"], "resp": 0, "exp": "G3a = 45-59; G3b = 30-44; G4 = 15-29; G5 < 15 mL/min/1,73 m²."}, {"t": "mem", "titulo": "Eletrólitos: valores de referência", "pares": [["Sódio", "135 - 145 mEq/L"], ["Potássio", "3,5 - 5,0 mEq/L"], ["Cálcio total", "8,5 - 10,5 mg/dL"], ["Magnésio", "1,5 - 2,5 mg/dL"], ["Fósforo", "2,5 - 4,5 mg/dL"], ["Cloro", "98 - 107 mEq/L"]]}, {"t": "vf", "afirm": "Na hipercalemia grave, o ECG mostra onda T apiculada e alargamento do QRS; o gluconato de cálcio é usado para estabilizar a membrana.", "resp": true, "exp": "Cálcio protege o miocárdio (não baixa o K); insulina+glicose e beta-2 deslocam para dentro da célula; diurético, resina e diálise removem."}, {"t": "fill", "frase": "A correção da hiponatremia crônica não deve ultrapassar ___ mEq/L em 24 h, pelo risco de mielinólise pontina.", "opcoes": ["8 - 10", "20 - 25", "2 - 3"], "resp": 0, "dica": "Sódio se corrige devagar: 'subiu rápido demais, desmielinizou'.", "exp": "Limite usual de 8-10 mEq/L/24 h (mais conservador em alto risco), para evitar síndrome de desmielinização osmótica."}, {"t": "quiz", "p": "Cálcio total 7,6 mg/dL e albumina 2,0 g/dL. Qual o cálcio corrigido?", "opcoes": ["9,2 mg/dL", "8,4 mg/dL", "7,6 mg/dL", "10,0 mg/dL"], "resp": 0, "exp": "Ca corrigido = Ca + 0,8 × (4 − albumina) = 7,6 + 0,8 × 2,0 = 9,2 mg/dL. Hipoalbuminemia simula hipocalcemia."}, {"t": "vf", "afirm": "Relação ureia/creatinina muito elevada (> 40) com creatinina pouco alterada sugere causa pré-renal.", "resp": true, "exp": "Na hipoperfusão há reabsorção ávida de ureia; some-se FENa < 1% e urina concentrada."}, {"t": "fill", "frase": "A creatinina sérica de referência no adulto fica em torno de ___ mg/dL.", "opcoes": ["0,6 - 1,2", "1,5 - 2,0", "0,1 - 0,3"], "resp": 0, "dica": "Creatinina depende de massa muscular: idoso magro pode ter TFG baixa com creatinina 'normal'.", "exp": "Referência usual: 0,6-1,2 mg/dL (homens) e 0,5-1,1 mg/dL (mulheres). Ureia: 15-45 mg/dL."}]}, {"titulo": "Glicêmico, lipídico e hepático", "mnemo": "Diabetes é 126 - 200 - 6,5 (jejum ≥126 | 2 h no TOTG ou casual com sintomas ≥200 | HbA1c ≥6,5%). Pré-diabetes é a faixa de baixo: 100-125 | 140-199 | 5,7-6,4%.", "itens": [{"t": "fill", "frase": "Glicemia de jejum ≥ ___ mg/dL, confirmada em segunda dosagem, fecha o diagnóstico de diabetes.", "opcoes": ["126", "100", "140", "200"], "resp": 0, "dica": "126 - 200 - 6,5: os três números do diagnóstico.", "exp": "Jejum ≥126 mg/dL, TOTG 2 h ≥200, HbA1c ≥6,5% ou glicemia casual ≥200 com sintomas clássicos."}, {"t": "quiz", "p": "Paciente assintomático com HbA1c de 6,0%. Como classificar?", "opcoes": ["Pré-diabetes", "Normal", "Diabetes tipo 2", "Diabetes gestacional"], "resp": 0, "exp": "HbA1c: <5,7% normal; 5,7-6,4% pré-diabetes; ≥6,5% diabetes (confirmar). Alvo terapêutico geral <7%."}, {"t": "vf", "afirm": "A HbA1c reflete a glicemia média dos últimos 2-3 meses e pode ser falsamente BAIXA na anemia hemolítica.", "resp": true, "exp": "Hemólise, sangramento e gestação encurtam a vida da hemácia e reduzem a HbA1c; ferropenia e uremia podem elevá-la falsamente."}, {"t": "fill", "frase": "Pela fórmula de Friedewald: LDL = Colesterol total − HDL − Triglicerídeos/___.", "opcoes": ["5", "3", "2"], "resp": 0, "dica": "Só vale em mg/dL e com triglicerídeos < 400 mg/dL.", "exp": "LDL = CT − HDL − TG/5. Com TG ≥400 a fórmula perde validade: dosar LDL direto. Não-HDL = CT − HDL."}, {"t": "mem", "titulo": "Lipidograma e hepatograma", "pares": [["Colesterol total", "< 190 mg/dL"], ["Triglicerídeos (jejum)", "< 150 mg/dL"], ["HDL desejável (homem)", "> 40 mg/dL"], ["AST e ALT", "até ~40 U/L"], ["Bilirrubina total", "0,3 - 1,2 mg/dL"], ["Albumina", "3,5 - 5,0 g/dL"]]}, {"t": "quiz", "p": "Relação AST/ALT > 2 com GGT elevada sugere:", "opcoes": ["Doença hepática alcoólica", "Hepatite viral aguda", "Esteatose não alcoólica", "Colestase por cálculo"], "resp": 0, "exp": "AST/ALT > 2 ('o Sáude do álcool') aponta lesão alcoólica. Nas hepatites virais e na esteatose predomina a ALT."}, {"t": "vf", "afirm": "Elevação predominante de fosfatase alcalina e GGT caracteriza padrão colestático.", "resp": true, "exp": "Padrão hepatocelular = ALT/AST altas; colestático = FA + GGT altas (a GGT confirma origem hepática da FA)."}, {"t": "quiz", "p": "Quais exames avaliam a FUNÇÃO de síntese do fígado?", "opcoes": ["Albumina e TP/INR", "AST e ALT", "GGT e fosfatase alcalina", "Bilirrubina indireta"], "resp": 0, "exp": "Albumina e fatores de coagulação (TP/INR) são sintetizados no fígado. Transaminases indicam lesão, não função."}]}, {"titulo": "Gasometria e distúrbios ácido-base", "mnemo": "ROME — Respiratório Oposto (pH e PaCO2 em direções opostas), Metabólico Equivalente (pH e HCO3 na mesma direção). Para acidose com ânion gap alto: MUDPILES.", "itens": [{"t": "fill", "frase": "Gasometria arterial normal: pH 7,35-7,45, HCO3 22-26 mEq/L e PaCO2 ___ mmHg.", "opcoes": ["35 - 45", "20 - 30", "50 - 60"], "resp": 0, "dica": "Sequência fácil: pH 7,35-7,45 / PaCO2 35-45 / HCO3 22-26.", "exp": "PaO2 80-100 mmHg e SatO2 95-98% completam o exame; BE ±3."}, {"t": "vf", "afirm": "Nos distúrbios respiratórios, pH e PaCO2 caminham em direções opostas; nos metabólicos, pH e HCO3 caminham juntos.", "resp": true, "exp": "É o ROME: Respiratório Oposto, Metabólico Equivalente. Primeiro olhe o pH, depois quem 'explica' a alteração."}, {"t": "quiz", "p": "pH 7,25 | PaCO2 30 mmHg | HCO3 13 mEq/L. O distúrbio é:", "opcoes": ["Acidose metabólica com compensação respiratória", "Acidose respiratória", "Alcalose metabólica", "Alcalose respiratória pura"], "resp": 0, "exp": "pH e HCO3 baixos juntos = metabólico (ROME). Winter: 1,5 × 13 + 8 = 27,5 ± 2 — a PaCO2 de 30 mostra compensação adequada."}, {"t": "fill", "frase": "Ânion gap = Na − (Cl + HCO3); o valor normal é de ___ mEq/L.", "opcoes": ["8 - 12", "20 - 25", "2 - 4"], "resp": 0, "dica": "Corrija o AG pela albumina: some 2,5 para cada 1 g/dL de albumina abaixo de 4.", "exp": "AG alto = acúmulo de ácidos (MUDPILES). AG normal = perda de bicarbonato (diarreia, acidose tubular renal, SF 0,9% em excesso)."}, {"t": "quiz", "p": "Qual dessas NÃO cursa com acidose metabólica de ânion gap AUMENTADO?", "opcoes": ["Diarreia intensa", "Cetoacidose diabética", "Intoxicação por salicilato", "Acidose lática por choque"], "resp": 0, "exp": "A diarreia perde bicarbonato e gera acidose hiperclorêmica com AG NORMAL. As outras entram no MUDPILES."}, {"t": "mem", "titulo": "MUDPILES: letra e causa", "pares": [["M", "Metanol"], ["U", "Uremia"], ["D", "Cetoacidose Diabética"], ["I", "Isoniazida / ferro (Iron)"], ["L", "Lactato"], ["S", "Salicilatos"]]}, {"t": "vf", "afirm": "Vômitos prolongados ou sonda nasogástrica aberta causam alcalose metabólica hipoclorêmica e hipocalêmica.", "resp": true, "exp": "Perda de HCl gástrico: cloro e potássio baixos, HCO3 alto. Responde a soro fisiológico + reposição de potássio."}, {"t": "quiz", "p": "A fórmula de Winter, que estima a compensação respiratória na acidose metabólica, é:", "opcoes": ["PaCO2 esperada = 1,5 × HCO3 + 8 ± 2", "PaCO2 esperada = HCO3 + 15", "PaCO2 esperada = 0,7 × HCO3 + 20", "PaCO2 esperada = 2 × HCO3"], "resp": 0, "exp": "Se a PaCO2 real for MAIOR que a esperada, há acidose respiratória associada; se for menor, alcalose respiratória associada."}]}, {"titulo": "Coagulação, marcadores cardíacos e inflamatórios", "mnemo": "WEPT & HIT — Warfarina (varfarina) = Extrínseca = TP/INR | Heparina = Intrínseca = TTPa. Guarde também: troponina para infarto, BNP para insuficiência cardíaca, D-dímero para excluir TEV.", "itens": [{"t": "fill", "frase": "A varfarina é monitorada pelo ___ , expresso como INR, que avalia a via extrínseca.", "opcoes": ["TP (tempo de protrombina)", "TTPa", "Tempo de trombina", "Fibrinogênio"], "resp": 0, "dica": "WEPT: Warfarina - Extrínseca - TP. Sobra para a heparina o TTPa (via intrínseca).", "exp": "A varfarina inibe os fatores dependentes de vitamina K (II, VII, IX, X); o fator VII, de meia-vida curta, alarga primeiro o TP."}, {"t": "quiz", "p": "Alvo de INR para a maioria das indicações de varfarina (ex.: fibrilação atrial, TEV):", "opcoes": ["2,0 - 3,0", "1,0 - 1,5", "3,5 - 4,5", "0,8 - 1,2"], "resp": 0, "exp": "Faixa terapêutica 2,0-3,0 (2,5-3,5 em prótese valvar mecânica mitral). INR sem anticoagulante: 0,8-1,2."}, {"t": "vf", "afirm": "A heparina não fracionada em dose plena é monitorada pelo TTPa, com alvo de 1,5 a 2,5 vezes o valor de controle.", "resp": true, "exp": "A heparina de baixo peso molecular não precisa de monitoramento de rotina (se necessário, anti-Xa)."}, {"t": "mem", "titulo": "Coagulação e marcadores", "pares": [["INR sem anticoagulante", "0,8 - 1,2"], ["TTPa", "25 - 35 segundos"], ["Fibrinogênio", "200 - 400 mg/dL"], ["D-dímero", "< 500 ng/mL"], ["NT-proBNP (exclui IC)", "< 125 pg/mL"], ["PCR", "< 3 mg/L"]]}, {"t": "quiz", "p": "Marcador mais sensível e específico de necrose miocárdica:", "opcoes": ["Troponina de alta sensibilidade", "CK-MB", "Mioglobina", "LDH"], "resp": 0, "exp": "A troponina (I ou T) sobe em 2-3 h, com curva seriada (0 e 1-3 h) e valor acima do percentil 99. CK-MB só é útil para reinfarto precoce."}, {"t": "vf", "afirm": "O D-dímero tem alto valor preditivo NEGATIVO: normal em paciente de baixa probabilidade, afasta tromboembolismo venoso.", "resp": true, "exp": "É pouco específico (sobe em infecção, câncer, gestação, pós-operatório e idade avançada), por isso serve para excluir, não para confirmar."}, {"t": "fill", "frase": "A ___ é o marcador que mais sugere infecção bacteriana e ajuda a guiar a suspensão do antibiótico quando cai.", "opcoes": ["procalcitonina", "VHS", "ferritina", "fosfatase alcalina"], "resp": 0, "dica": "Procalcitonina > 0,5 ng/mL favorece bactéria; PCR é sensível mas inespecífica; VHS sobe e desce devagar.", "exp": "A procalcitonina tem cinética rápida e é usada em protocolos de descalonamento antimicrobiano."}, {"t": "quiz", "p": "Queda de mais de 50% das plaquetas entre o 5º e o 10º dia de heparina sugere:", "opcoes": ["Trombocitopenia induzida por heparina (HIT)", "Púrpura trombocitopênica imune", "CIVD", "Anemia aplásica"], "resp": 0, "exp": "Na HIT o paciente TROMBOSA, apesar da plaquetopenia: suspender toda heparina e trocar por anticoagulante não heparínico."}]}]}, {"unidade": "Portaria 344/98", "icone": "📋", "licoes": [{"titulo": "As listas: quem é quem", "mnemo": "A de Alto risco (entorpecente) · B de Benzo (psicotrópico) · C de Controle especial · D de preDecessor (precursor) · E de Erva proscrita · F de Fora da lei (proscrita)", "itens": [{"t": "fill", "frase": "Morfina, fentanil e metadona são entorpecentes da lista ___.", "opcoes": ["A1", "A3", "B1", "C1"], "resp": 0, "dica": "A de Alto risco: A1 são os entorpecentes clássicos da dor.", "exp": "A1 = entorpecentes. A2 = entorpecentes permitidos só em baixas concentrações (ex.: codeína em associação). Ambas usam Notificação de Receita A."}, {"t": "quiz", "p": "Metilfenidato e lisdexanfetamina pertencem a qual lista?", "opcoes": ["A1", "A3", "B1", "C1"], "resp": 1, "exp": "A3 = psicotrópicos sob Notificação de Receita A (amarela). Desde 2018 anfepramona, femproporex e mazindol também foram alocados na A3."}, {"t": "mem", "titulo": "Lista x exemplo", "pares": [["A1 - entorpecente", "Morfina, fentanil, metadona"], ["A3 - psicotrópico", "Metilfenidato, lisdexanfetamina"], ["B1 - psicotrópico", "Diazepam, clonazepam, zolpidem"], ["B2 - anorexígeno", "Sibutramina"], ["C1 - controle especial", "Carbamazepina, amitriptilina"], ["C5 - anabolizante", "Testosterona, nandrolona"]]}, {"t": "vf", "afirm": "A lista C2 reúne os retinoides de uso sistêmico, como isotretinoína e acitretina.", "resp": true, "exp": "C2 = retinoides. Pense em C2 = 'Cútis': são os medicamentos da pele, teratogênicos, com controle reforçado."}, {"t": "vf", "afirm": "Cannabis sativa e Papaver somniferum estão na lista F (substâncias proscritas).", "resp": false, "exp": "Estão na lista E = plantas proscritas (E de Erva). A lista F é de substâncias de uso proscrito no Brasil (F1 entorpecentes como heroína, F2 psicotrópicos como LSD e MDMA)."}, {"t": "quiz", "p": "A lista D1 é composta por:", "opcoes": ["Anabolizantes esteroides", "Precursores de entorpecentes e psicotrópicos (ex.: efedrina, ergotamina, ácido lisérgico)", "Imunossupressores", "Plantas proscritas"], "resp": 1, "exp": "D de preDecessor: D1 são substâncias precursoras, matéria-prima para sintetizar entorpecentes/psicotrópicos, sujeitas a controle e Autorização Especial."}, {"t": "fill", "frase": "Talidomida e lenalidomida são imunossupressores da lista ___.", "opcoes": ["C1", "C2", "C3", "C5"], "resp": 2, "dica": "C3 tem T de Talidomida e T de Teratogênico.", "exp": "C3 = imunossupressores. A talidomida tem regramento próprio (RDC 11/2011): Notificação de Receita Especial + termo de esclarecimento e responsabilidade."}]}, {"titulo": "Cores e tipos de receituário", "mnemo": "A de Amarela (A1/A2/A3) · B de aBul = azul (B1/B2) · Especial é Branca (C2 e C3) · C1 e C5 não têm notificação: é Receita de Controle Especial em 2 vias", "itens": [{"t": "mem", "titulo": "Receituário x listas", "pares": [["NR A - amarela", "Listas A1, A2 e A3"], ["NR B - azul", "Listas B1 e B2"], ["NR Especial - branca", "Listas C2 e C3"], ["Controle Especial - 2 vias", "Listas C1 e C5"], ["Numeração da NR", "Fornecida pela VISA estadual"]]}, {"t": "fill", "frase": "Medicamentos da lista B1, como o clonazepam, exigem Notificação de Receita ___.", "opcoes": ["A (amarela)", "B (azul)", "Especial (branca)", "simples"], "resp": 1, "dica": "B de aBul: azul.", "exp": "B1 e B2 usam a Notificação de Receita B, de cor azul, retida na farmácia no ato da dispensação."}, {"t": "vf", "afirm": "A Notificação de Receita A é impressa pelo próprio prescritor.", "resp": false, "exp": "O talonário da NR A (amarela) é fornecido pela autoridade sanitária estadual. Já a NR B e a NR Especial são impressas pelo profissional ou instituição, com numeração concedida pela VISA."}, {"t": "quiz", "p": "A isotretinoína de uso oral é dispensada mediante:", "opcoes": ["Notificação de Receita A (amarela)", "Notificação de Receita B (azul)", "Notificação de Receita Especial (branca) + termo de consentimento pós-informação", "Receita simples, retida"], "resp": 2, "exp": "Retinoide sistêmico (C2) exige NR Especial branca e, pelo risco teratogênico, termo de consentimento; em mulheres em idade fértil há exigências adicionais de contracepção."}, {"t": "quiz", "p": "Retinoides de uso tópico (ex.: tretinoína creme) são dispensados mediante:", "opcoes": ["Notificação de Receita Especial (branca)", "Receita de Controle Especial em 2 vias", "Receita simples, sem retenção", "Notificação de Receita B (azul)"], "resp": 1, "exp": "Pegadinha clássica: retinoide sistêmico = NR Especial branca; retinoide tópico = Receita de Controle Especial em 2 vias."}, {"t": "vf", "afirm": "Uma Notificação de Receita pode conter mais de uma substância sujeita a controle especial.", "resp": false, "exp": "Cada Notificação de Receita comporta apenas UMA substância. Já a Receita de Controle Especial pode trazer até 3 substâncias."}, {"t": "fill", "frase": "A Receita de Controle Especial é emitida em ___ vias: a 1ª fica retida na farmácia e a 2ª volta ao paciente.", "opcoes": ["1", "2", "3", "4"], "resp": 1, "dica": "Controle especial = 2 vias: uma fica, uma volta.", "exp": "1ª via: 'Retenção da Farmácia'. 2ª via: 'Orientação ao Paciente'. É o receituário das listas C1 e C5."}, {"t": "vf", "afirm": "A Receita de Controle Especial pode conter no máximo 3 substâncias.", "resp": true, "exp": "Limite de 3 substâncias por receita de controle especial, ao contrário da Notificação de Receita, que admite apenas 1."}]}, {"titulo": "Validade e âmbito", "mnemo": "Quase tudo é 30 dias — só a talidomida é 20. Âmbito: A de todo o pAís (nacional), assim como a Receita de Controle Especial; aZul e branca ficam na UF que concedeu a numeração", "itens": [{"t": "fill", "frase": "A Notificação de Receita A tem validade de ___ dias a contar da data de emissão.", "opcoes": ["20", "30", "60", "90"], "resp": 1, "dica": "Regra dos 30: a maioria dos controlados vale 30 dias.", "exp": "NR A: 30 dias de validade e âmbito nacional — é a única notificação que atravessa o país."}, {"t": "mem", "titulo": "Validade e âmbito", "pares": [["NR A - amarela", "30 dias - todo o país"], ["NR B - azul", "30 dias - só na UF"], ["NR Especial C2 - branca", "30 dias - só na UF"], ["NR Especial C3 - talidomida", "20 dias"], ["Controle Especial C1/C5", "30 dias - todo o país"]]}, {"t": "vf", "afirm": "A Notificação de Receita B é válida em todo o território nacional.", "resp": false, "exp": "A NR B (azul) e a NR Especial (branca) valem apenas dentro da Unidade Federativa que concedeu a numeração."}, {"t": "quiz", "p": "Qual receituário de controlado tem validade em todo o território nacional?", "opcoes": ["Notificação de Receita B (azul)", "Notificação de Receita Especial (branca)", "Notificação de Receita A (amarela)", "Nenhum: todos são restritos à UF"], "resp": 2, "exp": "NR A = todo o pAís. A Receita de Controle Especial (C1/C5) também vale nacionalmente, mas ela não é notificação."}, {"t": "vf", "afirm": "A prescrição de talidomida tem validade de 20 dias.", "resp": true, "exp": "Talidomida (C3) é a exceção da regra dos 30: validade de 20 dias, com quantidade máxima para 30 dias de tratamento (RDC 11/2011)."}, {"t": "fill", "frase": "A validade da receita de controlado conta a partir da data de ___.", "opcoes": ["emissão", "dispensação", "retenção", "escrituração"], "resp": 0, "dica": "O relógio começa na caneta do prescritor, não no balcão.", "exp": "Conta-se da data de emissão. Receita vencida não pode ser dispensada, ainda que o paciente alegue atraso."}, {"t": "quiz", "p": "Receita de antimicrobiano (RDC 20/2011) tem validade de:", "opcoes": ["10 dias", "30 dias", "60 dias", "90 dias"], "resp": 0, "exp": "Contraste que cai em prova: antimicrobiano = 10 dias, 2 vias, retenção da 1ª via. Não é Portaria 344, mas divide o mesmo balcão e o SNGPC."}]}, {"titulo": "Quantidades máximas", "mnemo": "Ampola é sempre 5. Dias: 30 para o trio A-A-A (Amarela, Anorexígeno B2, Acne C2) e 60 para B1, C1 e C5", "itens": [{"t": "fill", "frase": "Na Notificação de Receita A, a quantidade máxima é de 5 ampolas ou tratamento para até ___ dias.", "opcoes": ["15", "30", "60", "90"], "resp": 1, "dica": "Amarela = 30 dias, igual à sua validade.", "exp": "NR A: até 5 ampolas; nas demais formas farmacêuticas, quantidade correspondente a no máximo 30 dias de tratamento."}, {"t": "quiz", "p": "Diazepam (lista B1): quantidade máxima por Notificação de Receita B?", "opcoes": ["5 ampolas ou 30 dias de tratamento", "5 ampolas ou 60 dias de tratamento", "10 ampolas ou 60 dias de tratamento", "Sem limite, a critério do prescritor"], "resp": 1, "exp": "B1: até 5 ampolas ou quantidade para até 60 dias de tratamento. A validade continua sendo 30 dias — não confunda validade com quantidade."}, {"t": "vf", "afirm": "A Notificação de Receita B de sibutramina (B2) pode cobrir até 60 dias de tratamento.", "resp": false, "exp": "B2 (anorexígenos) tem limite de 30 dias de tratamento. É a exceção dentro da notificação azul."}, {"t": "mem", "titulo": "Quantidade máxima", "pares": [["NR A (A1/A2/A3)", "5 ampolas ou 30 dias"], ["NR B - lista B1", "5 ampolas ou 60 dias"], ["NR B - lista B2", "30 dias de tratamento"], ["NR Especial - C2", "30 dias de tratamento"], ["Controle Especial C1/C5", "5 ampolas ou 60 dias"]]}, {"t": "fill", "frase": "Para carbamazepina (C1), a Receita de Controle Especial cobre no máximo ___ dias de tratamento.", "opcoes": ["20", "30", "60", "90"], "resp": 2, "dica": "C1 anda junto com B1: 60 dias.", "exp": "C1: até 5 ampolas ou quantidade para 60 dias de tratamento, em receita de controle especial de 2 vias válida por 30 dias."}, {"t": "vf", "afirm": "Para anabolizantes da lista C5 valem os mesmos limites da C1: 5 ampolas ou 60 dias de tratamento.", "resp": true, "exp": "C1 e C5 compartilham receituário (controle especial, 2 vias), validade (30 dias, nacional) e quantidade (5 ampolas ou 60 dias)."}, {"t": "quiz", "p": "A prescrição ultrapassa a quantidade máxima permitida. O farmacêutico deve:", "opcoes": ["Dispensar a quantidade prescrita, pois o prescritor é o responsável", "Dispensar somente até o limite legal, anotar na receita e contatar o prescritor", "Recusar e reter a receita definitivamente sem qualquer registro", "Fracionar o excedente para o mês seguinte com a mesma receita"], "resp": 1, "exp": "O limite quantitativo é legal e indisponível: dispensa-se até o teto, com registro do que foi fornecido e comunicação ao prescritor."}]}, {"titulo": "Escrituração, guarda e RDC 44/2009", "mnemo": "Tem NOTIFICAÇÃO (A e B), vai pra CHAVE. Escrituração hoje é eletrônica: SNGPC. Balanço da 344: trimestral até o dia 15 e anual até 31 de janeiro. Receita retida: arquivo por 2 anos", "itens": [{"t": "fill", "frase": "Os medicamentos das listas A1, A2, A3, B1 e B2 devem ser guardados ___.", "opcoes": ["na gôndola de autosserviço", "sob chave, em armário exclusivo e seguro", "na área de circulação de clientes", "sob refrigeração obrigatória"], "resp": 1, "dica": "Tem notificação de receita? Vai pra chave.", "exp": "Guarda sob chave (ou sistema de segurança equivalente), sob responsabilidade do farmacêutico, para as listas A e B."}, {"t": "vf", "afirm": "As notificações e receitas retidas devem ser mantidas na farmácia por 2 anos, à disposição da fiscalização.", "resp": true, "exp": "Prazo de guarda de 2 anos para receituário retido e para os livros/registros de controlados, contados do último lançamento."}, {"t": "quiz", "p": "O SNGPC é:", "opcoes": ["O sistema eletrônico da Anvisa para escrituração de controlados e antimicrobianos", "O livro físico de registro específico da farmácia", "O cadastro nacional de prescritores", "O sistema de notificação de reações adversas"], "resp": 0, "exp": "Sistema Nacional de Gerenciamento de Produtos Controlados: registra entradas e saídas das listas A, B, C2, C3, C5 e dos antimicrobianos."}, {"t": "mem", "titulo": "Controle e fiscalização", "pares": [["SNGPC", "Escrituração eletrônica (Anvisa)"], ["Balanço trimestral", "Até o dia 15 após o trimestre"], ["Balanço anual", "Até 31 de janeiro"], ["Guarda sob chave", "Listas A1/A2/A3/B1/B2"], ["Receitas retidas", "Arquivo por 2 anos"], ["RDC 44/2009", "Boas práticas em farmácia"]]}, {"t": "vf", "afirm": "Pela RDC 44/2009, medicamentos sujeitos a prescrição podem ficar em autosserviço, ao alcance do cliente.", "resp": false, "exp": "Só os isentos de prescrição podem ficar na área de circulação. Sujeitos a prescrição ficam atrás do balcão — e os controlados, sob chave."}, {"t": "fill", "frase": "A RDC ___/2009 estabelece as Boas Práticas Farmacêuticas para funcionamento e dispensação em farmácias e drogarias.", "opcoes": ["20", "44", "67", "302"], "resp": 1, "dica": "44 é a regra do balcão; 20 é a dos antimicrobianos.", "exp": "RDC 44/2009: boas práticas, presença do farmacêutico, serviços farmacêuticos com Declaração de Serviço e ambiente adequado."}, {"t": "quiz", "p": "Quem responde pela guarda, dispensação e escrituração dos controlados na farmácia?", "opcoes": ["O proprietário do estabelecimento", "O farmacêutico responsável técnico", "O atendente de balcão treinado", "A vigilância sanitária municipal"], "resp": 1, "exp": "A responsabilidade é do farmacêutico RT: dispensação, retenção, guarda sob chave e escrituração no SNGPC."}, {"t": "vf", "afirm": "A escrituração no SNGPC dispensa a drogaria de manter o livro de registro específico em papel.", "resp": true, "exp": "Com o SNGPC, a escrituração eletrônica substitui o livro de registro específico e os balanços em papel para os produtos abrangidos pelo sistema."}]}]}, {"unidade": "Segurança do Paciente", "icone": "🛡️", "licoes": [{"titulo": "PNSP, incidentes e queijo suíço", "mnemo": "CQSD — a escada do incidente: C = Circunstância notificável (só o risco existe), Q = Quase erro / near miss (não chegou ao paciente), S = incidente Sem dano (chegou, mas não lesou), D = incidente com Dano = evento adverso. Base legal: 529 (Portaria do PNSP) e 36 (RDC do NSP).", "itens": [{"t": "fill", "frase": "O Programa Nacional de Segurança do Paciente (PNSP) foi instituído pela Portaria MS nº ___, de 1º de abril de 2013.", "opcoes": ["36", "529", "4.283", "2.095"], "resp": 1, "dica": "Guarde o par: Portaria 529 cria o PROGRAMA; RDC 36 cria o NÚCLEO (NSP) no serviço de saúde.", "exp": "Portaria GM/MS 529/2013 institui o PNSP. A RDC ANVISA 36/2013 institui ações de segurança e obriga o Núcleo de Segurança do Paciente (NSP) e o Plano de Segurança do Paciente (PSP)."}, {"t": "quiz", "p": "O técnico separa heparina no lugar de enoxaparina, mas a dupla checagem intercepta a dose antes de chegar ao paciente. Como classificar?", "opcoes": ["Evento adverso", "Incidente sem dano", "Near miss (quase erro)", "Circunstância notificável"], "resp": 2, "exp": "Near miss é o incidente que NÃO atingiu o paciente (foi barrado antes). Se tivesse sido administrado sem lesão, seria incidente sem dano; com lesão, evento adverso."}, {"t": "vf", "afirm": "Todo erro de medicação que chega ao paciente é, por definição, um evento adverso.", "resp": false, "exp": "Falso. Evento adverso exige DANO. O erro que atinge o paciente sem causar lesão é 'incidente sem dano' — deve ser notificado do mesmo jeito."}, {"t": "fill", "frase": "No modelo do queijo suíço de Reason, os erros cometidos na ponta pelo profissional são as falhas ___, enquanto as decisões de gestão e falhas de sistema são as condições latentes.", "opcoes": ["ativas", "residuais", "sistêmicas", "terminais"], "resp": 0, "dica": "ATIVA = na Assistência (ponta, visível na hora). LATENTE = Lá atrás (gestão, dorme no sistema).", "exp": "Falhas ativas ocorrem no contato direto com o paciente; condições latentes (escala ruim, estoque mal desenhado, rótulo confuso) ficam adormecidas até alinharem os furos das barreiras."}, {"t": "mem", "titulo": "Ligue o conceito à definição", "pares": [["Near miss", "Não chegou ao paciente"], ["Evento adverso", "Atingiu e causou dano"], ["Falha ativa", "Erro na ponta da assistência"], ["Condição latente", "Falha do sistema, adormecida"], ["Circunstância notificável", "Só o risco, sem incidente"]]}, {"t": "vf", "afirm": "A cultura de segurança preconizada pelo PNSP é não punitiva: o foco da análise é o sistema, não a busca do culpado.", "resp": true, "exp": "Verdadeiro. É a cultura justa: notificar sem medo, analisar causa-raiz e corrigir o processo. Punir o indivíduo só faz a subnotificação crescer (mas imprudência e violação deliberada seguem respondendo)."}, {"t": "quiz", "p": "Qual é a atribuição típica do Núcleo de Segurança do Paciente (NSP) segundo a RDC 36/2013?", "opcoes": ["Prescrever ajustes de dose nos MPP", "Elaborar o Plano de Segurança e gerenciar as notificações de incidentes", "Dispensar medicamentos em dose unitária", "Substituir a Comissão de Farmácia e Terapêutica"], "resp": 1, "exp": "O NSP elabora/implanta o Plano de Segurança do Paciente, promove a cultura de segurança, monitora indicadores e gerencia as notificações de incidentes (NOTIVISA)."}, {"t": "fill", "frase": "Eventos adversos que evoluíram para óbito devem ser notificados à Anvisa (NOTIVISA) em até ___ horas.", "opcoes": ["24", "48", "72", "96"], "resp": 2, "dica": "Óbito = 72 h (3 dias). Os demais incidentes vão no consolidado mensal, até o 15º dia do mês seguinte.", "exp": "RDC 36/2013: incidentes com óbito em até 72 h da ocorrência; os demais, mensalmente, até o 15º dia do mês subsequente."}]}, {"titulo": "As 6 metas internacionais de segurança", "mnemo": "ICMCIQ — 'Idosos Comem Muito Caldo, Infelizmente Quente': I = Identificação correta do paciente; C = Comunicação efetiva; M = Medicamentos de alta vigilância (segurança na prescrição/uso); C = Cirurgia segura (paciente, local e procedimento certos); I = Infecção (higiene das mãos); Q = Quedas e lesão por pressão.", "itens": [{"t": "fill", "frase": "A Meta 1 exige identificar o paciente com, no mínimo, ___ identificadores antes de qualquer cuidado.", "opcoes": ["um", "dois", "três", "quatro"], "resp": 1, "dica": "O 'I' do ICMCIQ vem primeiro e pede DOIS: nome completo + data de nascimento (ou nº do prontuário).", "exp": "Dois identificadores, nunca o número do leito ou do quarto — leito muda, paciente troca de lugar."}, {"t": "vf", "afirm": "O número do leito é um identificador aceitável para conferir o paciente antes de administrar um medicamento.", "resp": false, "exp": "Falso. Leito e quarto são vetados justamente porque mudam. Use nome completo, data de nascimento, nome da mãe ou nº do prontuário, conferindo na pulseira."}, {"t": "quiz", "p": "Qual destas NÃO é uma das seis metas internacionais de segurança do paciente?", "opcoes": ["Reduzir o risco de quedas e lesão por pressão", "Melhorar a comunicação efetiva entre profissionais", "Reduzir o custo médio da prescrição hospitalar", "Higienizar as mãos para prevenir infecções"], "resp": 2, "exp": "Custo não é meta de segurança. As seis são: identificação, comunicação, medicamentos de alta vigilância, cirurgia segura, higiene das mãos e quedas/lesão por pressão."}, {"t": "mem", "titulo": "ICMCIQ: meta e sua ferramenta", "pares": [["Meta 1 - Identificação", "Pulseira + 2 identificadores"], ["Meta 2 - Comunicação", "SBAR e read-back da ordem verbal"], ["Meta 3 - Medicamentos", "Lista de MPP e dupla checagem"], ["Meta 4 - Cirurgia segura", "Checklist: sign in, time out, sign out"], ["Meta 5 - Infecção", "5 momentos de higiene das mãos"], ["Meta 6 - Quedas/lesão", "Escala de Morse e de Braden"]]}, {"t": "fill", "frase": "Na Meta 2, ao receber uma prescrição verbal ou por telefone, o profissional deve anotar e depois ___ a informação para quem prescreveu confirmar.", "opcoes": ["arquivar", "repetir de volta (read-back)", "assinar em duplicata", "digitalizar"], "resp": 1, "exp": "Anotar + ler de volta + confirmar (write down, read back, confirm). Ordens verbais devem ser exceção e precisam ser transcritas e validadas pelo prescritor."}, {"t": "quiz", "p": "No checklist de cirurgia segura da OMS, em que momento ocorre o 'time out'?", "opcoes": ["Antes da entrada do paciente no centro cirúrgico", "Antes da indução anestésica", "Antes da incisão cirúrgica, com toda a equipe parada", "Antes de o paciente sair da sala"], "resp": 2, "exp": "Sign in (antes da anestesia), time out (antes da incisão, toda a equipe confirma paciente/local/procedimento) e sign out (antes de o paciente deixar a sala)."}, {"t": "vf", "afirm": "O uso de luvas substitui a higiene das mãos entre um paciente e outro.", "resp": false, "exp": "Falso. A luva não substitui a higienização: as mãos devem ser higienizadas antes de calçar e após retirar as luvas, seguindo os 5 momentos da OMS."}]}, {"titulo": "Os 9 certos, LASA e dupla checagem", "mnemo": "PMDVHRODR — Paciente, Medicamento, Dose, Via, Horário, Registro, Orientação ao paciente, Direito de recusar e Resposta (monitorar o efeito). Os 5 primeiros são o preparo, os 4 últimos são o depois — o erro mais esquecido mora no fim da lista.", "itens": [{"t": "fill", "frase": "No mnemônico PMDVHRODR, a letra V corresponde ao certo da ___.", "opcoes": ["validade", "via de administração", "vazão", "verificação"], "resp": 1, "dica": "P-M-D-V-H = Paciente, Medicamento, Dose, Via, Horário: é a sequência da beira do leito.", "exp": "Via certa: trocar EV por IM, ou administrar por via errada uma formulação (ex.: solução oral por via EV), é erro grave e frequentemente fatal."}, {"t": "quiz", "p": "Enfermeira vai administrar vancomicina em 'Maria Silva Santos', leito 12. Há outra 'Maria Silva Souza' na mesma enfermaria. Qual conduta atende ao 1º certo?", "opcoes": ["Confirmar pelo leito, que é único", "Perguntar em voz alta 'quem é Maria?' na enfermaria", "Conferir pulseira com nome completo e data de nascimento", "Confiar na etiqueta impressa pela farmácia"], "resp": 2, "exp": "Nomes semelhantes exigem dois identificadores conferidos na pulseira. Perguntar em voz alta induz resposta afirmativa automática do paciente."}, {"t": "vf", "afirm": "O 'registro certo' permite checar a administração na prescrição antes de administrar, para não esquecer depois.", "resp": false, "exp": "Falso. Checagem prévia é erro clássico: registra-se o que não foi feito. O registro é sempre IMEDIATAMENTE APÓS a administração."}, {"t": "mem", "titulo": "PMDVHRODR: letra e significado", "pares": [["P e M", "Paciente certo e Medicamento certo"], ["D e V", "Dose certa e Via certa"], ["H", "Horário certo"], ["R (6º)", "Registro logo após administrar"], ["O e D (7º e 8º)", "Orientar e respeitar a recusa"], ["R (9º)", "Resposta: monitorar efeito e RAM"]]}, {"t": "fill", "frase": "Para reduzir trocas entre medicamentos LASA (nomes parecidos), o ISMP recomenda destacar em maiúsculas a parte que diferencia os nomes, técnica chamada ___.", "opcoes": ["tall man lettering", "barcode scanning", "tall dose", "rotulagem cega"], "resp": 0, "exp": "Tall man lettering: DOPAmina x DOBUTamina, clorproPAMIDA x clorproMAZINA. Some-se armazenagem separada, alerta na prateleira e não guardar por ordem alfabética pura."}, {"t": "quiz", "p": "O que caracteriza uma dupla checagem INDEPENDENTE de um medicamento de alta vigilância?", "opcoes": ["Dois profissionais conferem juntos, um lendo em voz alta para o outro", "Dois profissionais conferem separadamente, sem saber o resultado do outro", "O mesmo profissional confere duas vezes, com intervalo", "O farmacêutico confere e o enfermeiro assina"], "resp": 1, "exp": "Independente = cada um calcula/confere sozinho e só depois comparam. Conferir junto contamina o segundo checador pelo viés de confirmação."}, {"t": "vf", "afirm": "O paciente lúcido tem o direito de recusar um medicamento, e essa recusa deve ser registrada e comunicada ao prescritor.", "resp": true, "exp": "Verdadeiro. O 'direito de recusar' é um dos 9 certos: registre a recusa, o motivo e comunique a equipe — nunca administre à força ou disfarçado."}, {"t": "fill", "frase": "O 9º certo, a 'resposta certa', significa ___ após a administração.", "opcoes": ["descartar o frasco corretamente", "monitorar o efeito esperado e as reações adversas", "arquivar a prescrição", "devolver a sobra à farmácia"], "resp": 1, "dica": "O último R fecha o ciclo: Resposta = o que aconteceu com o PACIENTE, não com o frasco.", "exp": "Monitorar eficácia (dor cedeu? PA caiu?) e segurança (RAM), documentar e notificar. É o certo mais negligenciado na prática."}]}, {"titulo": "Medicamentos potencialmente perigosos e erros de medicação", "mnemo": "AIOK-QBS — os grandes MPP: A = Anticoagulantes (heparina, varfarina), I = Insulinas, O = Opioides, K = potássio e demais eletrólitos concentrados, Q = Quimioterápicos, B = Bloqueadores neuromusculares, S = Sedativos/anestésicos. Regra do K: eletrólito concentrado não fica na enfermaria.", "itens": [{"t": "fill", "frase": "A recomendação clássica do ISMP para o cloreto de potássio 19,1% é ___ das unidades de internação, mantendo-o sob controle da farmácia.", "opcoes": ["a retirada", "a duplicação do estoque", "a diluição prévia pelo enfermeiro", "o armazenamento junto ao soro fisiológico"], "resp": 0, "dica": "O K do AIOK: 'K fora da enfermaria'. Ampola concentrada trocada por água destilada mata em minutos.", "exp": "Eletrólitos concentrados (KCl, NaCl 20%, sulfato de magnésio) devem sair das unidades; a farmácia dispensa já diluído, rotulado e por dose."}, {"t": "quiz", "p": "Qual destes NÃO integra tipicamente a lista de medicamentos potencialmente perigosos (MPP/alta vigilância) do ISMP Brasil?", "opcoes": ["Insulina regular", "Heparina não fracionada", "Dipirona sódica", "Bloqueadores neuromusculares"], "resp": 2, "exp": "Dipirona não é MPP. MPP são os que, quando erram, causam dano grave — anticoagulantes, insulinas, opioides, eletrólitos concentrados, quimioterápicos, bloqueadores neuromusculares e sedativos."}, {"t": "vf", "afirm": "Medicamentos potencialmente perigosos são aqueles em que os erros acontecem com maior frequência.", "resp": false, "exp": "Falso. A frequência do erro não é maior; o que é maior é a GRAVIDADE do dano quando o erro ocorre. Por isso exigem barreiras extras (dupla checagem, alerta, padronização)."}, {"t": "mem", "titulo": "AIOK-QBS: risco e barreira", "pares": [["Anticoagulante", "Sangramento; antídoto vit. K/protamina"], ["Insulina", "Hipoglicemia; nunca abreviar 'U'"], ["Opioide", "Depressão respiratória; naloxona"], ["KCl concentrado", "Parada cardíaca; fora da enfermaria"], ["Bloqueador neuromuscular", "Apneia; rótulo 'paralisante'"], ["Quimioterápico", "Extravasamento; preparo em CFLV"]]}, {"t": "fill", "frase": "Na prescrição de insulina, a abreviatura 'U' deve ser substituída pela palavra ___ para evitar leitura como zero.", "opcoes": ["unidades", "ampolas", "mL", "frascos"], "resp": 0, "dica": "'10U' vira '100': o U cola no número. Escreva por extenso — vale também para não usar zero à direita (1,0 mg vira 10 mg).", "exp": "Abreviaturas perigosas: U/UI, 'µg' (usar mcg), zero à direita (1,0) e ausência de zero à esquerda (,5). Todas já causaram erros de 10x."}, {"t": "quiz", "p": "Farmacêutico dispensa metotrexato 2,5 mg com posologia diária, quando a prescrição correta era semanal, e o paciente usa por 7 dias. Como se classifica o incidente?", "opcoes": ["Near miss, pois o erro foi da prescrição", "Evento adverso decorrente de erro de medicação", "Reação adversa idiossincrásica, não evitável", "Circunstância notificável"], "resp": 1, "exp": "Houve dano evitável ligado ao processo do medicamento: evento adverso por erro. Reação adversa é o dano com dose e uso corretos; erro é o dano evitável."}, {"t": "vf", "afirm": "A análise farmacêutica da prescrição é a principal barreira para interceptar erros de prescrição antes que cheguem ao paciente.", "resp": true, "exp": "Verdadeiro. A validação farmacêutica (dose, via, diluição, interações, função renal) intercepta grande parte dos erros — cada erro interceptado é um near miss a notificar."}]}, {"titulo": "Dose unitária, curva ABC e conciliação", "mnemo": "CCCD (conciliação) — Coletar a melhor história medicamentosa, Comparar com a prescrição, Conciliar/Comunicar as divergências ao prescritor, Documentar. E a curva ABC: classe A = poucos itens (~20%) e muito dinheiro (~80%).", "itens": [{"t": "fill", "frase": "O sistema de distribuição em que cada medicamento é dispensado pronto para uso, identificado e separado por paciente e horário chama-se dose ___.", "opcoes": ["coletiva", "unitária", "individualizada", "mista"], "resp": 1, "dica": "Unitária = 1 dose, 1 paciente, 1 horário. Individualizada é por paciente, mas em embalagem múltipla; coletiva é o estoque solto na enfermaria.", "exp": "A dose unitária é o sistema mais seguro: reduz erros de administração, perdas, desvios e permite a validação farmacêutica de cada prescrição."}, {"t": "quiz", "p": "Na curva ABC de estoque, o que caracteriza os itens da classe A?", "opcoes": ["Cerca de 20% dos itens e 80% do valor investido", "Cerca de 80% dos itens e 20% do valor", "Os itens de maior risco clínico", "Os itens termolábeis"], "resp": 0, "exp": "ABC é critério econômico (Pareto): A = ~20% dos itens e ~80% do valor, exigem controle rigoroso; B intermediário; C = muitos itens, pouco valor. Risco clínico é a classificação XYZ/criticidade."}, {"t": "vf", "afirm": "A conciliação medicamentosa deve ser feita apenas no momento da alta hospitalar.", "resp": false, "exp": "Falso. É obrigatória nas três transições de cuidado: admissão, transferência interna e alta — é aí que se perdem ou se duplicam medicamentos de uso crônico."}, {"t": "mem", "titulo": "Logística e transição de cuidado", "pares": [["Dose unitária", "Pronta por paciente e horário"], ["Dose coletiva", "Estoque na unidade: maior risco"], ["Curva ABC", "Classifica por valor (Pareto)"], ["Conciliação", "Compara uso prévio x prescrição"], ["Discrepância intencional", "Mudança proposital do prescritor"], ["Discrepância não intencional", "Omissão ou troca não percebida"]]}, {"t": "fill", "frase": "No mnemônico CCCD, o primeiro passo da conciliação é ___ a melhor história medicamentosa possível, usando o paciente, receitas, caixas e prontuário.", "opcoes": ["coletar", "comparar", "comunicar", "documentar"], "resp": 0, "dica": "Coletar → Comparar → Conciliar/Comunicar → Documentar. Sem o primeiro C, os outros três conciliam a informação errada.", "exp": "A melhor história medicamentosa usa no mínimo duas fontes (entrevista + receitas/embalagens/registro eletrônico) e inclui fitoterápicos, isentos de prescrição e colírios."}, {"t": "quiz", "p": "Na admissão, o paciente usa metformina em casa e a prescrição hospitalar não a contém, sem justificativa no prontuário. Trata-se de:", "opcoes": ["Discrepância intencional documentada", "Discrepância não intencional (omissão) a comunicar ao prescritor", "Reação adversa", "Erro de dispensação"], "resp": 1, "exp": "Omissão sem justificativa = discrepância não intencional, o achado mais comum da conciliação. O farmacêutico comunica ao prescritor e documenta a resolução."}, {"t": "vf", "afirm": "O sistema de distribuição coletiva é o que apresenta maior risco de erro de medicação e maior perda por validade.", "resp": true, "exp": "Verdadeiro. Com estoque solto na unidade, não há validação farmacêutica por dose, aumentam trocas, desvios e vencimentos. Por isso a tendência é dose unitária/individualizada."}, {"t": "fill", "frase": "Além da segurança, a dispensação em dose unitária aumenta o controle do estoque porque permite a ___ das doses não administradas à farmácia.", "opcoes": ["devolução", "reembalagem clandestina", "incineração", "doação"], "resp": 0, "dica": "Dose unitária fecha o ciclo: sai identificada, volta rastreada.", "exp": "A devolução das doses não administradas fecha o balanço, reduz perdas e ainda funciona como indicador — muita devolução aponta falha na administração ou na prescrição."}]}]}, {"unidade": "Farmacovigilância & Epidemiologia", "icone": "📈", "licoes": [{"titulo": "RAM tipo A x tipo B", "mnemo": "A de Aumentada e Antecipável (dose-dependente, comum, pouco letal, resolve reduzindo a dose). B de Bizarra (imprevisível, rara, mais letal, resolve suspendendo o fármaco).", "itens": [{"t": "fill", "frase": "A RAM tipo ___ é dose-dependente, previsível pela farmacologia, tem alta incidência e baixa letalidade.", "opcoes": ["A", "B", "C", "D"], "resp": 0, "dica": "A de Aumentada (Augmented): é o próprio efeito farmacológico exagerado.", "exp": "Tipo A = ampliação do efeito esperado (hipoglicemia por insulina, bradicardia por betabloqueador). Costuma responder à redução de dose."}, {"t": "quiz", "p": "Anafilaxia à penicilina, sem relação com a dose administrada, é RAM de que tipo?", "opcoes": ["Tipo A", "Tipo B", "Tipo C", "Tipo E"], "resp": 1, "exp": "Reação imunoalérgica, independente da dose e imprevisível = tipo B (Bizarra). A conduta é suspender e contraindicar o fármaco, não reduzir a dose."}, {"t": "vf", "afirm": "A RAM tipo A tem baixa incidência e alta mortalidade.", "resp": false, "exp": "É o inverso: tipo A tem ALTA incidência e BAIXA mortalidade; o tipo B é raro, porém proporcionalmente mais grave e letal."}, {"t": "mem", "titulo": "Tipo A x Tipo B", "pares": [["Tipo A — Aumentada", "Dose-dependente e previsível"], ["Tipo B — Bizarra", "Imprevisível, independe da dose"], ["Exemplo de tipo A", "Hipoglicemia por insulina"], ["Exemplo de tipo B", "Anafilaxia por penicilina"], ["Conduta no tipo A", "Reduzir a dose"], ["Conduta no tipo B", "Suspender o fármaco"]]}, {"t": "fill", "frase": "Sangramento por varfarina em paciente com INR 6,0 é RAM tipo ___, por ser extensão do efeito anticoagulante.", "opcoes": ["A", "B", "D", "F"], "resp": 0, "dica": "Se dá para prever pela farmacologia e piora com a dose, é A.", "exp": "Efeito farmacológico exagerado = tipo A. Evitável com monitorização (INR) e ajuste de dose."}, {"t": "quiz", "p": "Qual característica NÃO pertence à RAM tipo B?", "opcoes": ["É imprevisível", "Depende da dose administrada", "Tem baixa incidência", "Envolve idiossincrasia ou alergia"], "resp": 1, "exp": "O tipo B não é dose-dependente: pode ocorrer com dose mínima. Depender da dose é a assinatura do tipo A."}, {"t": "vf", "afirm": "A maioria das RAM observadas na prática clínica é do tipo A.", "resp": true, "exp": "Cerca de 80% das RAM são tipo A — justamente por isso são as mais evitáveis, com ajuste de dose, revisão de interações e monitorização."}, {"t": "fill", "frase": "A hemólise por primaquina em deficiência de G6PD é uma reação ___, exemplo clássico de RAM tipo B.", "opcoes": ["idiossincrásica", "colateral", "de rebote", "dose-dependente"], "resp": 0, "dica": "Idiossincrasia = resposta 'estranha', geneticamente determinada → B de Bizarra.", "exp": "Idiossincrasia e hipersensibilidade são os dois mecanismos típicos do tipo B: um genético/metabólico, outro imunológico."}]}, {"titulo": "Classificação A–F das RAM", "mnemo": "ABCDEF: A-umentada, B-izarra, C-rônica (dose cumulativa), D-emorada/tardia, E-ncerramento do uso (retirada), F-alha terapêutica.", "itens": [{"t": "fill", "frase": "Osteonecrose de mandíbula após uso prolongado de bisfosfonato é RAM tipo ___, ligada à dose cumulativa.", "opcoes": ["B", "C", "D", "F"], "resp": 1, "dica": "C de Chronic/Crônica — depende do total acumulado e do tempo de uso.", "exp": "Tipo C aparece com uso continuado; a conduta envolve reavaliar a duração do tratamento e as 'férias terapêuticas'."}, {"t": "fill", "frase": "A síndrome de retirada após suspensão abrupta do propranolol é RAM tipo ___.", "opcoes": ["C", "D", "E", "F"], "resp": 2, "dica": "E de End of use — o problema aparece no Encerramento do tratamento.", "exp": "Efeito rebote/abstinência é tipo E. Prevenção: desmame gradual (betabloqueador, clonidina, corticoide, benzodiazepínico, ISRS)."}, {"t": "quiz", "p": "Gravidez em usuária de contraceptivo oral que iniciou rifampicina caracteriza RAM tipo:", "opcoes": ["Tipo C", "Tipo D", "Tipo E", "Tipo F"], "resp": 3, "exp": "Tipo F = Failure/falha terapêutica inesperada. A rifampicina induz o CYP3A4 e reduz os níveis do contraceptivo — falha por interação."}, {"t": "mem", "titulo": "Letra ↔ significado", "pares": [["A — Augmented", "Aumentada, dose-dependente"], ["B — Bizarre", "Bizarra, imprevisível"], ["C — Chronic", "Crônica, dose cumulativa"], ["D — Delayed", "Demorada, surge tempos depois"], ["E — End of use", "Retirada, rebote, abstinência"], ["F — Failure", "Falha terapêutica inesperada"]]}, {"t": "vf", "afirm": "A RAM tipo C depende da dose cumulativa e do tempo de uso, enquanto a tipo D aparece tardiamente, mesmo após exposição breve.", "resp": true, "exp": "Essa é a pegadinha clássica: C = tempo de EXPOSIÇÃO longo; D = tempo de LATÊNCIA longo (teratogênese, carcinogênese)."}, {"t": "quiz", "p": "Supressão do eixo hipotálamo-hipófise-adrenal por corticoide sistêmico prolongado é RAM tipo:", "opcoes": ["A", "B", "C", "F"], "resp": 2, "exp": "Tipo C (crônica), pois depende do tempo e da dose acumulada. Se a crise adrenal surgir na retirada abrupta, o evento passa a ser tipo E."}, {"t": "fill", "frase": "Adenocarcinoma vaginal em filhas de mulheres que usaram dietilestilbestrol na gestação é RAM tipo ___.", "opcoes": ["B", "C", "D", "E"], "resp": 2, "dica": "D de Delayed/Demorada — anos (ou uma geração) entre a exposição e o efeito.", "exp": "Tipo D reúne teratogênese e carcinogênese. Pela latência longa, quase sempre é detectada em estudos caso-controle, não em ensaios clínicos."}, {"t": "vf", "afirm": "A RAM tipo E ocorre no pico de concentração do medicamento.", "resp": false, "exp": "Tipo E (End of use) ocorre na SUSPENSÃO: abstinência ou rebote — como a crise hipertensiva após parada abrupta da clonidina."}]}, {"titulo": "Causalidade, notificação e vigilância", "mnemo": "Escada de Naranjo, do topo para baixo: ≥9 Definida, 5–8 Provável, 1–4 Possível, ≤0 Duvidosa. E no Brasil quem recebe a suspeita é o VigiMed.", "itens": [{"t": "fill", "frase": "No algoritmo de Naranjo, escore igual ou maior que 9 classifica a reação como ___.", "opcoes": ["duvidosa", "possível", "provável", "definida"], "resp": 3, "dica": "Desça a escada: 9 Definida, 5 Provável, 1 Possível, 0 ou menos Duvidosa.", "exp": "O Naranjo tem 10 perguntas e varia de −4 a +13 pontos. É o algoritmo mais cobrado por ser objetivo e reprodutível."}, {"t": "quiz", "p": "Paciente com escore de Naranjo igual a 6. Qual a classificação de causalidade?", "opcoes": ["Definida", "Provável", "Possível", "Duvidosa"], "resp": 1, "exp": "Faixa de 5 a 8 pontos = provável. Abaixo disso (1 a 4) seria apenas possível, e 9 ou mais, definida."}, {"t": "vf", "afirm": "A melhora da reação após a retirada do medicamento (dechallenge positivo) soma pontos no algoritmo de Naranjo.", "resp": true, "exp": "Sim, e a reexposição positiva (rechallenge) pontua ainda mais, sendo o critério de causalidade mais forte — embora raramente seja ético provocá-la."}, {"t": "fill", "frase": "No Brasil, a notificação de suspeitas de eventos adversos a medicamentos é feita no sistema ___, da Anvisa.", "opcoes": ["VigiMed", "Notivisa", "SinanNet", "SNGPC"], "resp": 0, "dica": "VigiMed = vigilância de MEDicamentos; o Notivisa ficou com os demais produtos sob vigilância sanitária.", "exp": "O VigiMed (derivado do VigiFlow, da OMS/Uppsala) tem uma porta de entrada para profissionais e cidadãos e outra para detentores de registro."}, {"t": "vf", "afirm": "Só se deve notificar um evento adverso quando a relação causal com o medicamento já estiver comprovada.", "resp": false, "exp": "Notifica-se a SUSPEITA. Exigir causalidade comprovada aumentaria a subnotificação e atrasaria a geração de sinais de segurança."}, {"t": "quiz", "p": "Qual alternativa descreve corretamente a farmacovigilância ATIVA?", "opcoes": ["Depende do relato voluntário do profissional que atendeu o caso", "Busca sistemática e planejada dos eventos, como monitorização intensiva de pacientes internados ou coorte de eventos ligados à prescrição", "É sinônimo de notificação espontânea informatizada", "Só pode ser feita pelo detentor do registro do medicamento"], "resp": 1, "exp": "Ativa = o serviço vai atrás do evento (busca em prontuários, rastreadores, registros, coortes). Passiva = espera a notificação espontânea chegar."}, {"t": "mem", "titulo": "Conceitos de farmacovigilância", "pares": [["Notificação espontânea", "Farmacovigilância passiva"], ["Busca ativa em prontuários", "Farmacovigilância ativa"], ["Sinal", "Associação nova a investigar"], ["DDD", "Dose diária definida (adulto)"], ["ATC", "Classificação em 5 níveis"], ["Estudo de fase IV", "Pós-comercialização"]]}, {"t": "fill", "frase": "O consumo hospitalar de antimicrobianos costuma ser expresso em ___ por 100 leitos-dia.", "opcoes": ["DDD", "UI", "mg/kg", "DL50"], "resp": 0, "dica": "DDD = Dose Diária Definida: unidade técnica de medida, não recomendação de dose.", "exp": "A DDD é a dose de manutenção presumida no adulto para a indicação principal, atribuída pela OMS junto ao código ATC (nível 1 anatômico, ex.: J = anti-infecciosos sistêmicos)."}]}, {"titulo": "Fases I–IV, desenhos e frequência", "mnemo": "Fases: 1 Sadios (segurança), 2 Serve? (dose e eficácia inicial), 3 Superior? (ECR grande), 4 Sobrevive no mercado (farmacovigilância). E: coorte segue o EXPOSTO, caso-controle começa no DOENTE.", "itens": [{"t": "fill", "frase": "Os estudos de fase ___ são feitos em poucos voluntários sadios e avaliam segurança e farmacocinética.", "opcoes": ["I", "II", "III", "IV"], "resp": 0, "dica": "Fase 1 = Sadios.", "exp": "Fase I: 20 a 100 voluntários sadios, foco em tolerabilidade, dose máxima tolerada e perfil cinético. Em oncologia, usa-se pacientes."}, {"t": "quiz", "p": "Ensaio randomizado multicêntrico com 3.000 pacientes comparando o novo fármaco ao tratamento padrão, antes do registro, corresponde à fase:", "opcoes": ["I", "II", "III", "IV"], "resp": 2, "exp": "Fase III: eficácia comparativa em grande escala, base do pedido de registro. A fase II (100–300 pacientes) apenas explora dose e eficácia inicial."}, {"t": "vf", "afirm": "Estudos de fase IV ocorrem após a comercialização e podem detectar RAM raras que não apareceram nas fases anteriores.", "resp": true, "exp": "As fases I–III têm n limitado e população selecionada; reações raras (< 1:10.000) e efeitos em idosos, gestantes e crianças só emergem no uso real."}, {"t": "fill", "frase": "O estudo de ___ parte da exposição e acompanha os participantes até o desfecho, permitindo calcular incidência e risco relativo.", "opcoes": ["coorte", "caso-controle", "transversal", "ecológico"], "resp": 0, "dica": "Coorte segue o EXPOSTO; caso-controle começa no DOENTE.", "exp": "A coorte é o melhor desenho observacional para exposição rara e para medir incidência, mas é cara e ineficiente para doença rara."}, {"t": "quiz", "p": "Para investigar um fármaco suspeito de causar hepatite fulminante (evento raro), o desenho mais eficiente é:", "opcoes": ["Coorte prospectiva", "Caso-controle", "Transversal", "Ensaio clínico randomizado"], "resp": 1, "exp": "Caso-controle começa no DOENTE e olha para trás em busca da exposição: ideal para doença rara ou de latência longa. Fornece odds ratio, não incidência."}, {"t": "mem", "titulo": "Desenho ↔ marca registrada", "pares": [["Coorte", "Segue o exposto; dá incidência"], ["Caso-controle", "Começa no doente; dá odds ratio"], ["Transversal", "Foto do momento; dá prevalência"], ["Ecológico", "Unidade é a população"], ["Ensaio randomizado", "Alocação sorteada; maior nível"], ["Relato de caso", "Gera hipótese; sem controle"]]}, {"t": "fill", "frase": "Casos NOVOS surgidos em um período, divididos pela população em risco, definem a ___.", "opcoes": ["incidência", "prevalência", "letalidade", "mortalidade"], "resp": 0, "dica": "IncidêNcia = casos Novos; Prevalência = casos Presentes (novos + antigos).", "exp": "Só a incidência mede risco de adoecer. A prevalência mistura casos novos e antigos e é a medida típica do estudo transversal."}, {"t": "vf", "afirm": "Uma doença crônica cujo tratamento prolonga a sobrevida tende a ter prevalência maior que a incidência.", "resp": true, "exp": "Prevalência ≈ incidência × duração média da doença. Aumentando a duração (mais sobrevida), a prevalência sobe mesmo com incidência estável."}]}, {"titulo": "RR, OR, NNT e vieses", "mnemo": "RR e OR: >1 risco, <1 proteção, =1 indiferente. Absoluta SUBTRAI, relativa DIVIDE. NNT = 1/RRA, sempre arredondado para CIMA — NNT baixo e NNH alto é o cenário bom.", "itens": [{"t": "quiz", "p": "Coorte: 40 de 200 expostos e 10 de 200 não expostos tiveram o desfecho. O risco relativo é:", "opcoes": ["0,25", "2", "4", "8"], "resp": 2, "exp": "Risco nos expostos = 40/200 = 0,20; nos não expostos = 10/200 = 0,05. RR = 0,20 ÷ 0,05 = 4, ou seja, 4 vezes o risco."}, {"t": "quiz", "p": "Caso-controle: 40 casos expostos e 10 não expostos; 20 controles expostos e 30 não expostos. A odds ratio é:", "opcoes": ["2", "3", "6", "12"], "resp": 2, "exp": "OR = (40 × 30) ÷ (10 × 20) = 1200 ÷ 200 = 6. É a multiplicação cruzada (ad/bc). Quando a doença é rara, a OR aproxima bem o RR."}, {"t": "fill", "frase": "Se o desfecho ocorre em 20% no grupo controle e em 15% no grupo tratado, a redução ABSOLUTA de risco é de ___.", "opcoes": ["5%", "25%", "33%", "75%"], "resp": 0, "dica": "Absoluta SUBTRAI (20 − 15 = 5); relativa DIVIDE pelo risco basal (5 ÷ 20 = 25%).", "exp": "RRA = 5 pontos percentuais e RRR = 25%. A medida relativa parece maior com o mesmo dado — por isso é a preferida na propaganda de medicamentos."}, {"t": "quiz", "p": "Com redução absoluta de risco de 5%, qual é o número necessário para tratar (NNT)?", "opcoes": ["5", "10", "20", "25"], "resp": 2, "exp": "NNT = 1 ÷ RRA = 1 ÷ 0,05 = 20: tratar 20 pacientes para evitar 1 desfecho. Quanto menor o NNT, maior o benefício; arredonde sempre para cima."}, {"t": "vf", "afirm": "O NNH é 1 dividido pelo aumento absoluto de risco e, quanto MAIOR, melhor o perfil de segurança do fármaco.", "resp": true, "exp": "NNH = número de pacientes tratados para causar 1 dano. O cenário desejável é NNT baixo (benefício fácil) e NNH alto (dano difícil)."}, {"t": "mem", "titulo": "Medida ↔ fórmula", "pares": [["Risco relativo (RR)", "Risco exposto ÷ não exposto"], ["Odds ratio (OR)", "Cruzada: (a × d) ÷ (b × c)"], ["RRA", "Risco controle − risco tratado"], ["RRR", "RRA ÷ risco do controle"], ["NNT", "1 ÷ RRA"], ["NNH", "1 ÷ aumento absoluto de risco"]]}, {"t": "quiz", "p": "Qual é a diferença central entre viés e fator de confusão?", "opcoes": ["O viés pode ser corrigido na análise; a confusão, não", "A confusão pode ser controlada na análise (estratificação, ajuste, pareamento); o viés, uma vez cometido, não sai da pesquisa", "Ambos são corrigidos aumentando o tamanho da amostra", "A confusão só ocorre em ensaios clínicos randomizados"], "resp": 1, "exp": "Confundimento é a mistura do efeito de um terceiro fator ligado à exposição e causa do desfecho — controlável por randomização, restrição, estratificação ou regressão. Viés é erro sistemático de seleção ou aferição e não melhora com mais n."}, {"t": "vf", "afirm": "O viés de memória (recall) é típico dos estudos de caso-controle.", "resp": true, "exp": "Quem adoeceu tende a recordar melhor as exposições passadas do que os controles, distorcendo a odds ratio. É uma forma de viés de informação."}]}]}, {"unidade": "Cuidado Farmacêutico & Cardiologia", "icone": "❤️", "licoes": [{"titulo": "Processo de cuidado: PRM x RNM", "mnemo": "NES — as 3 categorias de RNM (3º Consenso de Granada): N = Necessidade (problema não tratado OU medicamento desnecessário); E = Efetividade (inefetividade não quantitativa e quantitativa); S = Segurança (insegurança não quantitativa e quantitativa). São 3 categorias × 2 subtipos = 6 RNM. E lembre: PRM = causa no Processo; RNM = Resultado negativo já medido no paciente.", "itens": [{"t": "fill", "frase": "O ___ é a causa (falha no processo de uso) e o RNM é o resultado negativo já observado no paciente.", "opcoes": ["PRM", "RAM", "EAM", "DDD"], "resp": 0, "dica": "PRM = P de Processo/causa; RNM = R de Resultado.", "exp": "PRM (problema relacionado a medicamento) é o risco/causa: dose errada, interação, não adesão. Se esse processo falho gerar dano ou falha terapêutica mensurável, vira RNM."}, {"t": "quiz", "p": "Idoso com PA 168x100 mmHg em 3 aferições e nenhum anti-hipertensivo prescrito. Qual RNM?", "opcoes": ["Necessidade: problema de saúde não tratado", "Inefetividade quantitativa", "Insegurança não quantitativa", "Necessidade: efeito de medicamento desnecessário"], "resp": 0, "exp": "Existe problema de saúde que exigiria farmacoterapia e ela não está presente — RNM de necessidade por problema não tratado. O outro polo da mesma categoria é o medicamento sem indicação."}, {"t": "vf", "afirm": "Todo RNM de segurança é dose-dependente.", "resp": false, "exp": "A insegurança pode ser quantitativa (depende da dose, ex.: hipoglicemia por insulina em excesso) ou não quantitativa (independe da dose, ex.: anafilaxia por penicilina)."}, {"t": "mem", "titulo": "Caso × categoria de RNM", "pares": [["HAS sem tratamento", "Necessidade"], ["Dose subterapêutica", "Inefetividade quantitativa"], ["Falha com dose adequada", "Inefetividade não quantit."], ["Alergia à penicilina", "Insegurança não quantit."], ["Sangramento por dose alta", "Insegurança quantitativa"]]}, {"t": "fill", "frase": "No método Dáder, a fase que organiza, em uma data concreta, os problemas de saúde e os medicamentos em uso é o ___.", "opcoes": ["estado de situação", "estudo", "resultado da intervenção", "oferta do serviço"], "resp": 0, "dica": "É a 'fotografia' do paciente naquele dia.", "exp": "Sequência do Dáder: oferta do serviço → 1ª entrevista → estado de situação → fase de estudo → fase de avaliação → fase de intervenção → resultado da intervenção → entrevistas sucessivas."}, {"t": "quiz", "p": "No registro SOAP, o resultado da creatinina sérica entra em qual componente?", "opcoes": ["S (subjetivo)", "O (objetivo)", "A (avaliação)", "P (plano)"], "resp": 1, "exp": "S = relato do paciente (queixas, adesão referida); O = dados mensuráveis (exames, PA, peso); A = análise farmacoterapêutica com identificação de PRM/RNM; P = plano e metas monitoráveis."}, {"t": "vf", "afirm": "A intervenção farmacêutica pode ser verbal ou escrita, com ou sem o prescritor, mas o resultado dela sempre precisa ser registrado e reavaliado.", "resp": true, "exp": "No Dáder, cada intervenção tem desfecho documentado (aceita/não aceita, problema resolvido/não resolvido) — sem isso não há seguimento, só orientação pontual."}, {"t": "quiz", "p": "Serviço em que o farmacêutico assume responsabilidade pelas necessidades do paciente ligadas a medicamentos, com acompanhamento contínuo e registro:", "opcoes": ["Dispensação", "Seguimento farmacoterapêutico", "Rastreamento em saúde", "Conciliação medicamentosa"], "resp": 1, "exp": "Seguimento é longitudinal e pactuado. A revisão da farmacoterapia é pontual; a conciliação é de transição de cuidado; a dispensação é o ato de entrega com orientação."}]}, {"titulo": "Conciliação e adesão (OMS)", "mnemo": "SEDTP — 'SE Deu Tempo Para' aderir: S = Socioeconômicos (custo, transporte, apoio familiar); E = Equipe e sistema de saúde (acesso, vínculo, desabastecimento); D = Doença/condição (sintomas ausentes, depressão, demência); T = Terapia (nº de doses, efeitos adversos, complexidade); P = Paciente (crenças, esquecimento, letramento). São as 5 dimensões da adesão da OMS.", "itens": [{"t": "fill", "frase": "No mnemônico SEDTP, a letra E corresponde à dimensão relacionada à ___.", "opcoes": ["equipe e ao sistema de saúde", "escolaridade do paciente", "eficácia do fármaco", "estrutura familiar"], "resp": 0, "dica": "E de Equipe: vínculo, acesso à consulta e ao medicamento.", "exp": "Falta de vínculo, consulta curta, fila e desabastecimento derrubam a adesão tanto quanto o esquecimento do paciente."}, {"t": "quiz", "p": "Paciente abandona o esquema porque toma 4 comprimidos/dia e tem muitos efeitos adversos. Qual dimensão da OMS predomina?", "opcoes": ["Socioeconômica", "Relacionada à terapia", "Relacionada à condição", "Relacionada ao paciente"], "resp": 1, "exp": "Complexidade posológica e efeitos adversos são fatores da terapia. Conduta: simplificar (dose única diária, combinação fixa) e manejar a reação adversa."}, {"t": "vf", "afirm": "Como a dimensão 'paciente' é a mais importante das cinco, a não adesão é essencialmente responsabilidade dele.", "resp": false, "exp": "A OMS descreve as 5 dimensões como interdependentes, sem hierarquia, justamente para tirar o foco de culpabilizar o paciente."}, {"t": "mem", "titulo": "Como medir adesão", "pares": [["Teste de Morisky-Green", "Autorrelato (4 perguntas)"], ["Contagem de comprimidos", "Método indireto simples"], ["Dosagem sérica do fármaco", "Método direto"], ["PDC ou MPR ≥ 80%", "Adesão considerada adequada"], ["Frasco eletrônico (MEMS)", "Registra cada abertura"]]}, {"t": "quiz", "p": "Qual é um método DIRETO de avaliar adesão?", "opcoes": ["Registro de dispensação na farmácia", "Contagem de comprimidos", "Dosagem sérica ou urinária do fármaco", "Questionário de Morisky"], "resp": 2, "exp": "Diretos: dosagem do fármaco/metabólito, marcador biológico, terapia diretamente observada. Os demais são indiretos (mais baratos, porém superestimam a adesão)."}, {"t": "fill", "frase": "A discrepância ___ é a diferença entre a lista prévia e a prescrição atual sem justificativa clínica documentada — ou seja, um erro de medicação.", "opcoes": ["não intencional", "intencional documentada", "posológica", "terapêutica"], "resp": 0, "dica": "Intencional = o médico quis; não intencional = ninguém quis.", "exp": "Discrepâncias intencionais podem ser documentadas (ok) ou não documentadas (exigem esclarecimento). As não intencionais — omissão, dose ou via trocada — são os erros que a conciliação previne."}, {"t": "vf", "afirm": "A conciliação medicamentosa deve ser feita na admissão, nas transferências internas e na alta hospitalar.", "resp": true, "exp": "Toda transição de cuidado é ponto de risco. Na alta, entregar lista escrita e conferida com o paciente reduz reinternação."}, {"t": "quiz", "p": "Melhor prática para a etapa inicial da conciliação na admissão:", "opcoes": ["Copiar a prescrição da última internação", "Obter a melhor história medicamentosa possível usando ≥ 2 fontes e comparar com a prescrição", "Perguntar apenas ao acompanhante", "Aguardar a alta para revisar tudo de uma vez"], "resp": 1, "exp": "Entrevista com o paciente/cuidador + receitas, caixas, prontuário e registro de dispensação. Incluir fitoterápicos, isentos de prescrição e colírios, que costumam ser omitidos."}]}, {"titulo": "Hipertensão: classes e metas", "mnemo": "ABCD dos anti-hipertensivos: A = IECA ('-pril') ou BRA ('-sartana'); B = Betabloqueador (só por indicação específica: pós-IAM, IC com FE reduzida, arritmia, gestante com labetalol); C = bloqueador de Canal de Cálcio (anlodipino); D = Diurético tiazídico (clortalidona, indapamida, hidroclorotiazida). A, C e D são de 1ª linha; o B entra por indicação, e A + BRA nunca se combinam.", "itens": [{"t": "quiz", "p": "Qual classe NÃO é considerada de primeira linha na HAS não complicada?", "opcoes": ["Diurético tiazídico", "Bloqueador de canal de cálcio", "Betabloqueador", "IECA"], "resp": 2, "exp": "Betabloqueador só é 1ª linha quando há indicação associada (pós-IAM, ICFEr, arritmia, enxaqueca, gestação com labetalol) — isoladamente protege menos contra AVC."}, {"t": "fill", "frase": "PA confirmada de 150x95 mmHg no consultório classifica hipertensão ___.", "opcoes": ["estágio 1", "pré-hipertensão", "estágio 2", "estágio 3"], "resp": 0, "dica": "140/90 → 160/100 → 180/110: cada degrau, um estágio.", "exp": "Estágio 1: 140-159 e/ou 90-99; estágio 2: 160-179 e/ou 100-109; estágio 3: ≥180 e/ou ≥110. Pré-hipertensão: 130-139 e/ou 85-89."}, {"t": "vf", "afirm": "Associar IECA a BRA é uma estratégia recomendada para potencializar a queda da PA.", "resp": false, "exp": "Duplo bloqueio do sistema renina-angiotensina aumenta hipercalemia, hipotensão e lesão renal aguda sem ganho de desfecho — é contraindicado."}, {"t": "mem", "titulo": "Anti-hipertensivo × efeito adverso", "pares": [["Enalapril", "Tosse seca e angioedema"], ["Anlodipino", "Edema de tornozelo"], ["Hidroclorotiazida", "Hipopotassemia"], ["Espironolactona", "Ginecomastia e hiperpotassemia"], ["Atenolol", "Bradicardia e broncoespasmo"]]}, {"t": "quiz", "p": "Qual anti-hipertensivo é contraindicado na gestação?", "opcoes": ["Metildopa", "Nifedipino de liberação prolongada", "Losartana", "Hidralazina"], "resp": 2, "exp": "IECA e BRA são teratogênicos (oligoidrâmnio, lesão renal fetal) em qualquer trimestre. Preferir metildopa, nifedipino ou labetalol/hidralazina."}, {"t": "fill", "frase": "Para o hipertenso de alto risco cardiovascular, a diretriz brasileira sugere meta de PA de ___ mmHg, desde que bem tolerada.", "opcoes": ["120-129/70-79", "menos de 160/100", "menos de 150/90", "menos de 180/110"], "resp": 0, "dica": "Alto risco = alvo mais apertado; idoso frágil = < 140/90.", "exp": "Meta inicial de <140/90 para todos; nos de alto risco cardiovascular busca-se 120-129/70-79. Em idosos frágeis ou muito idosos, priorizar <140/90 e vigiar hipotensão postural."}, {"t": "vf", "afirm": "Na HAS estágio 2, o início preferencial é com dois fármacos em doses baixas, de preferência em combinação fixa.", "resp": true, "exp": "Combinações preferidas: IECA ou BRA + BCC, ou IECA/BRA + tiazídico. A combinação fixa melhora a adesão e alcança a meta mais rápido."}, {"t": "quiz", "p": "Paciente iniciou enalapril há 10 dias. O que o farmacêutico deve priorizar na monitorização laboratorial?", "opcoes": ["Creatinina e potássio", "TGO e TGP", "Hemograma completo", "TSH e T4 livre"], "resp": 0, "exp": "Reavaliar função renal e potássio em 7-14 dias. Aumento de creatinina até ~30% pode ser tolerado; acima disso ou K >5,5 mEq/L, reavaliar a dose e procurar estenose de artéria renal."}]}, {"titulo": "IC: 4 pilares e SCA", "mnemo": "ABCD dos 4 pilares da ICFEr: A = Antagonista mineralocorticoide (espironolactona/eplerenona); B = Betabloqueador com evidência (carvedilol, bisoprolol, succinato de metoprolol); C = 'C' de Coração, o bloqueio do sistema renina-angiotensina (IECA, BRA ou ARNI sacubitril/valsartana — o preferido); D = Dapagliflozina/empagliflozina (iSGLT2). Diurético de alça alivia congestão, mas NÃO é pilar. Na SCA, o par é DAPT = AAS + inibidor de P2Y12.", "itens": [{"t": "fill", "frase": "O pilar 'D' do ABCD da insuficiência cardíaca com fração de ejeção reduzida é ___.", "opcoes": ["a dapagliflozina (iSGLT2)", "o diurético de alça", "a digoxina", "o diltiazem"], "resp": 0, "dica": "D de Dapa, não de diurético.", "exp": "iSGLT2 reduzem mortalidade e hospitalização independentemente de diabetes. Furosemida trata sintoma congestivo; diltiazem/verapamil são contraindicados na ICFEr por inotropismo negativo."}, {"t": "quiz", "p": "Qual betabloqueador NÃO tem evidência de redução de mortalidade na ICFEr?", "opcoes": ["Carvedilol", "Bisoprolol", "Succinato de metoprolol", "Atenolol"], "resp": 3, "exp": "Somente carvedilol, bisoprolol, succinato de metoprolol e nebivolol (idosos) têm evidência. Atenção: tartarato de metoprolol também não serve como substituto do succinato."}, {"t": "vf", "afirm": "Ao trocar enalapril por sacubitril/valsartana é necessário aguardar 36 horas sem o IECA.", "resp": true, "exp": "O washout de 36 h evita angioedema pelo acúmulo de bradicinina. Vindo de BRA, não é preciso intervalo."}, {"t": "mem", "titulo": "Pilar da IC × cuidado", "pares": [["Espironolactona", "Vigiar potássio e creatinina"], ["Sacubitril/valsartana", "36 h de intervalo após IECA"], ["Carvedilol", "Iniciar baixo, paciente compensado"], ["Dapagliflozina", "ITU e candidíase genital"], ["Furosemida", "Alivia sintoma, não é pilar"]]}, {"t": "quiz", "p": "Esquema antiplaquetário padrão após infarto com stent, na ausência de alto risco de sangramento:", "opcoes": ["AAS isolado por 12 meses", "AAS + inibidor de P2Y12 por 12 meses", "Clopidogrel isolado por 6 meses", "AAS + varfarina por 12 meses"], "resp": 1, "exp": "DAPT por 12 meses, preferindo ticagrelor ou prasugrel ao clopidogrel na SCA. Em alto risco hemorrágico, encurta-se a dupla; em alto risco isquêmico, pode-se prolongar."}, {"t": "fill", "frase": "O ___ é contraindicado em paciente com AVC ou AIT prévio.", "opcoes": ["prasugrel", "clopidogrel", "ticagrelor", "AAS"], "resp": 0, "dica": "Prasugrel: potente, porém proibido com AVC prévio e cauteloso se ≥75 anos ou <60 kg.", "exp": "No TRITON-TIMI 38, pacientes com AVC/AIT prévio tiveram dano líquido com prasugrel por hemorragia intracraniana."}, {"t": "vf", "afirm": "Quando associado ao ticagrelor, o AAS de manutenção deve ficar em dose baixa (até 100 mg/dia).", "resp": true, "exp": "Doses de AAS acima de 100 mg reduzem o benefício do ticagrelor (análise do PLATO) e aumentam sangramento."}, {"t": "quiz", "p": "Efeito adverso característico do ticagrelor, útil para o farmacêutico antecipar na orientação:", "opcoes": ["Tosse seca", "Dispneia", "Ginecomastia", "Edema de tornozelo"], "resp": 1, "exp": "Dispneia (geralmente leve, transitória, sem hipoxemia) e pausas ventriculares. Orientar antes evita abandono do antiagregante por susto."}]}, {"titulo": "FA, LDL e monitorização", "mnemo": "CHA2DS2-VA (ESC 2024 — sem o 'Sc', o sexo saiu do escore): C = insuficiência Cardíaca (1); H = Hipertensão (1); A2 = Age ≥ 75 anos (2); D = Diabetes (1); S2 = Stroke/AIT/tromboembolismo prévio (2); V = doença Vascular — IAM prévio, arteriopatia periférica, placa aórtica (1); A = Age 65-74 anos (1). Máximo 8 pontos: ≥2 indica anticoagulação; 1 ponto, considerar.", "itens": [{"t": "fill", "frase": "No CHA2DS2-VA, o item 'S2' vale 2 pontos e corresponde a ___.", "opcoes": ["AVC, AIT ou tromboembolismo prévio", "sexo feminino", "estenose mitral", "síndrome coronariana aguda"], "resp": 0, "dica": "Os dois itens de 2 pontos são os 'A2' de idade ≥75 e 'S2' de Stroke.", "exp": "Evento tromboembólico prévio é o maior preditor de recorrência. O sexo feminino deixou de pontuar na versão CHA2DS2-VA (ESC 2024)."}, {"t": "quiz", "p": "Paciente com FA, CHA2DS2-VA 4 e HAS-BLED 3. Conduta correta:", "opcoes": ["Suspender a anticoagulação pelo risco de sangramento", "Anticoagular e corrigir os fatores de sangramento modificáveis, com reavaliação mais frequente", "Trocar o anticoagulante por AAS", "Usar apenas metade da dose do anticoagulante"], "resp": 1, "exp": "HAS-BLED alto sinaliza vigilância, não contraindicação. Modificáveis: PA descontrolada, AINE/antiplaquetário concomitante, álcool e INR lábil. AAS não substitui anticoagulante na FA."}, {"t": "vf", "afirm": "Em paciente com prótese valvar mecânica, a rivaroxabana é preferida à varfarina.", "resp": false, "exp": "DOAC é contraindicado em prótese mecânica e em estenose mitral moderada a grave de origem reumática — nesses casos, varfarina com INR alvo definido pela prótese."}, {"t": "mem", "titulo": "Alvos e antídotos", "pares": [["INR alvo na FA", "2,0 a 3,0"], ["Antídoto da varfarina", "Vitamina K"], ["Antídoto da dabigatrana", "Idarucizumabe"], ["Digoxina na IC", "0,5 a 0,9 ng/mL"], ["LDL no risco muito alto", "Abaixo de 50 mg/dL"]]}, {"t": "quiz", "p": "Paciente pós-infarto (risco cardiovascular muito alto). Meta de LDL-c pela diretriz brasileira de dislipidemias:", "opcoes": ["< 130 mg/dL", "< 100 mg/dL", "< 70 mg/dL", "< 50 mg/dL"], "resp": 3, "exp": "Risco muito alto: LDL <50 mg/dL (a ESC adota <55) com redução ≥50% do basal. Alto risco <70; intermediário <100; baixo <130."}, {"t": "fill", "frase": "As estatinas de alta intensidade, capazes de reduzir o LDL em ≥ 50%, são ___.", "opcoes": ["atorvastatina 40-80 mg e rosuvastatina 20-40 mg", "sinvastatina 20 mg", "pravastatina 40 mg", "fluvastatina 40 mg"], "resp": 0, "dica": "Alta intensidade = só as duas mais potentes, em dose alta.", "exp": "Sinvastatina 80 mg está proscrita por miopatia; com anlodipino, o teto da sinvastatina é 20 mg/dia. Se precisar de fibrato junto da estatina, usar fenofibrato — nunca genfibrozila."}, {"t": "vf", "afirm": "A hipopotassemia aumenta o risco de intoxicação digitálica mesmo com digoxinemia dentro da faixa.", "resp": true, "exp": "O potássio baixo facilita a ligação da digoxina à Na+/K+-ATPase. Atenção redobrada em quem usa furosemida ou tiazídico junto. Sinais: náusea, visão amarelada (xantopsia), bradiarritmias."}, {"t": "quiz", "p": "Qual interação obriga a reduzir a dose de digoxina em cerca de 50% e reforçar a monitorização?", "opcoes": ["Amiodarona", "Omeprazol", "Metformina", "Losartana"], "resp": 0, "exp": "Amiodarona (e também verapamil, propafenona, claritromicina) inibe a glicoproteína-P e eleva a digoxinemia. A coleta deve ser feita pelo menos 6-8 h após a dose, para não medir a fase de distribuição."}]}]}];
